(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c16"]=[{"id":"00004540","register_sub_id":"101","register_pk":"105530","name":"旧山一林組製糸事務所","kana":"きゅうやまいちばやしぐみせいしじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県岡谷市中央町1-13-17","lat":36.061237,"lng":138.04685193,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺一部亜鉛メッキ鋼板葺、建築面積316㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"20 － 0184","desc":"正面２４ｍ奥行１３ｍ規模，寄棟造，桟瓦葺の木造２階建で，正面中央西寄りに玄関車寄，２階軒に切妻破風を付ける。外装は大オーダー風の柱型を除いて煉瓦タイル張とし，上げ下げ窓を規則的に穿つ。岡谷を代表する製糸会社の本社事務所建築の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004540"},{"id":"00004541","register_sub_id":"101","register_pk":"105531","name":"旧山一林組製糸守衛所","kana":"きゅうやまいちばやしぐみせいししゅえいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県岡谷市中央町1-13-17","lat":36.06144542,"lng":138.04687017,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、亜鉛メッキ鋼板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"20 － 0185","desc":"事務所玄関車寄の北方に位置する正門の東脇に東西棟で建つ。下見板張の木造平屋建で，屋根は鉄板葺で，東を寄棟造，西を半寄棟造とし，南面に戸口を設け，西妻面に受付窓口を開ける。事務所とともに，岡谷における生糸生産施設の最盛期の面影を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004541"},{"id":"00013544","register_sub_id":"101","register_pk":"504911","name":"小泉家住宅店舗兼主屋","kana":"こいずみけじゅうたくてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市中央四丁目6716-イ他","lat":36.40706944,"lng":138.25114722,"geo_status":"db","era":"明治前期／平成28年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"20 － 0568","desc":"上田城北東の染物業などを営んだ商家。道路に南面して建つ二階建切妻造に越屋根を掲げ、正面に下屋を付す。外壁は漆喰塗で、二階はたちが高く開口を大きくとる。内部は東を土間、西を居室とし、西端にも細い通り土間を通す。旧城下の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013544"},{"id":"00003095","register_sub_id":"101","register_pk":"104085","name":"坂井銘醸寛政蔵","kana":"さかいめいじょうかんせいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.491219,"lng":138.150513,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積185㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0115","desc":"主屋の西方に位置し，屋敷地のほぼ中央に南北棟で建つ。桁行１２間規模の長大な切妻造，桟瓦葺の２階建土蔵で，中央に通路を開けた長屋門風の外観を呈する。階下はもと米蔵で，階高を高くとっていることが西面の２段の窓配置からも窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003095"},{"id":"00003096","register_sub_id":"101","register_pk":"104086","name":"坂井銘醸慶応蔵","kana":"さかいめいじょうけいおうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.491405,"lng":138.150696,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積165㎡","structure_material":"土蔵造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0116","desc":"主屋の西方に位置し，宝暦蔵と寛政蔵との間に東西棟で建つ。切妻造，桟瓦葺の平屋建土蔵で，西半を麹室とし，主屋寄りの東半を釜場に充てる。釜場部は麹室部より棟を一段落としたつくりとし，棟中央に越屋根を載せ，東妻面近くに煙突を建てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003096"},{"id":"00003099","register_sub_id":"101","register_pk":"104089","name":"坂井銘醸昭和蔵","kana":"さかいめいじょうしょうわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.491405,"lng":138.150452,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積242㎡","structure_material":"土蔵造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0119","desc":"宝暦蔵の西方，酒造場の西北隅部に南北棟で建つ。桁行１２間梁間６間規模，切妻造，桟瓦葺の平屋建仕込蔵で，内部は板張，小屋組はキングポストトラスとする。外部腰は人造石仕上げとし，高い位置の窓には鉄製持送り付きの小庇をつけて外観意匠を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003099"},{"id":"00003098","register_sub_id":"101","register_pk":"104088","name":"坂井銘醸大正蔵","kana":"さかいめいじょうたいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.49148491,"lng":138.15089908,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積116㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0118","desc":"主屋の西方，宝暦蔵の南に接して建つ。東西棟，切妻造，桟瓦葺の木造２階建で，西面は慶応蔵釜場部の東北隅に食い込んだつくりとなる。杜氏，職方，奉公人等の宿泊居住棟で「広敷」と呼ばれる。造り酒屋の屋敷構えをつくる主要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003098"},{"id":"00003094","register_sub_id":"101","register_pk":"104084","name":"坂井銘醸宝暦蔵","kana":"さかいめいじょうほうれきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.491505,"lng":138.150696,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積377㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0114","desc":"文庫蔵の西方に続く，東西棟，切妻造，桟瓦葺の長大な２階建土蔵で，江戸時代以来の仕込蔵（酒造蔵）とされ，南方の釜場・麹室と並んで建つ。北面の低い位置に開けられた窓配置に特徴があり，昭和蔵とともに駅前通りに造り酒屋特有の景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003094"},{"id":"00003097","register_sub_id":"101","register_pk":"104087","name":"坂井銘醸明治蔵","kana":"さかいめいじょうめいじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.491245,"lng":138.150955,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積93㎡","structure_material":"土蔵造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0117","desc":"主屋の西南方，寛政蔵の東方に位置する。桁行７間規模，東西棟，切妻造，桟瓦葺，平入の平屋建土蔵で，主屋背面裏庭に続く作業場に面して建つ。もと精米所で，北面屋根を葺き下ろして北面側に細長の作業スペースをつくっている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003097"},{"id":"00006228","register_sub_id":"101","register_pk":"107212","name":"塩屋醸造うわみせ","kana":"しおやじょうぞううわみせ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655876,"lng":138.315659,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積35㎡、門付","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0304","desc":"主屋の西隣に位置し，市道に沿い北面して建つ。桁行３間，梁間３間半規模，塗屋造２階建，平入の切妻造，桟瓦葺。１階は土間と板の間を配して店とし，２階はもと隠居部屋で，６畳の座敷２室を配する。２階正面軒を出桁造とし，主屋と趣の異なる外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006228"},{"id":"00006231","register_sub_id":"101","register_pk":"107215","name":"塩屋醸造穀蔵","kana":"しおやじょうぞうこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655571,"lng":138.315643,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積59㎡","structure_material":"土蔵造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0307","desc":"敷地の西端，手造蔵南隣に東面して建つ。桁行４間半，梁間４間，土蔵造平屋建，切妻造，桟瓦葺。内部は真壁造で，小屋組を和小屋とし，長大な梁を用いる。正面外観は間口幅に庇を付け，上部に窓を２つ並べる。全体に丁寧なつくりとし，敷地景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006231"},{"id":"00006229","register_sub_id":"101","register_pk":"107213","name":"塩屋醸造醤油蔵","kana":"しおやじょうぞうしょゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.65583,"lng":138.315582,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積162㎡","structure_material":"土蔵造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0305","desc":"うわみせ西側に接して，市道沿いに建つ。桁行１１間半，梁間４間規模，土蔵造平屋建，切妻造，桟瓦葺，東面，平入りとする。街路側に大きな妻を見せ，外壁中央に格子付の大きな窓を開き，楣部を虹梁形に整える等，街路沿いに堂々とした外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006229"},{"id":"00006230","register_sub_id":"101","register_pk":"107214","name":"塩屋醸造手造蔵","kana":"しおやじょうぞうてづくりぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655666,"lng":138.315643,"geo_status":"db","era":"江戸後期／昭和60改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積122㎡、煉瓦造室付","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0306","desc":"敷地の西端，醤油蔵南隣に東面して建つ。桁行６間，梁間６間規模，木造２階建，切妻造，桟瓦葺。内部に明治後期に造られた煉瓦造の麹室を２室設ける。外壁は中塗仕上げで，正面に庇を付けた戸口を設ける。規模が大きく，醸造施設の景観を形成する要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006230"},{"id":"00006234","register_sub_id":"101","register_pk":"107218","name":"塩屋醸造文庫蔵","kana":"しおやじょうぞうぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655716,"lng":138.31585544,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0310","desc":"主屋の南方に位置し，北面して建つ。桁行３間半，梁間２間半，土蔵造２階建，切妻造，桟瓦葺。外壁は漆喰塗，腰壁は正面を海鼠壁とし，他３面は下見板張。戸口は楣部を虹梁形に整え，掛子塗戸を吊り込む。窓枠や鉢巻等に黒漆喰を用い，風格ある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006234"},{"id":"00006233","register_sub_id":"101","register_pk":"107217","name":"塩屋醸造味噌蔵","kana":"しおやじょうぞうみそぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655464,"lng":138.315872,"geo_status":"db","era":"江戸後／明治初期増築・平成5改修","year":1790,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後","structure":"土蔵造平屋建、瓦葺、建築面積185㎡","structure_material":"土蔵造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0309","desc":"敷地の南端に位置し北面して建つ。桁行１４間，梁間４間，土蔵造平屋建。屋根は桟瓦葺の切妻造で，西側５間は明治初期に増築したものである。外壁は漆喰塗で，内部を２室に分け，それぞれの正面に戸口を設ける。規模が大きく，景観の要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006233"},{"id":"00006232","register_sub_id":"101","register_pk":"107216","name":"塩屋醸造諸味蔵","kana":"しおやじょうぞうもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655445,"lng":138.315674,"geo_status":"db","era":"江戸後期／平成6改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積93㎡","structure_material":"土蔵造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0308","desc":"敷地の南西隅に位置し，東面して建つ。桁行７間，梁間４間，土蔵造平屋建，切妻造，桟瓦葺。内部は真壁造，小屋組を和小屋とし，長大な梁を用いる。外壁は中塗仕上げで，腰を下見板張とする。簡素なつくりであるが，規模が大きく，醸造施設景観の要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006232"},{"id":"00007628","register_sub_id":"101","register_pk":"108610","name":"笑亀酒造穀蔵","kana":"しょうきしゅぞうこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県塩尻市大字塩尻町字町141-1","lat":36.103798,"lng":137.9743159,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積123㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0345","desc":"店舗兼主屋の西側に建つ。桁行１８ｍ梁間７．３ｍ規模の２階建土蔵。切妻造で、置屋根式の桟瓦葺とし、東面北寄りに下屋を付ける。１・２階境の高さまで海鼠壁とし、妻面に大小の窓を穿ち、格子を入れる。旧中山道沿いに面して建つ、重厚な構えの大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007628"},{"id":"00007629","register_sub_id":"101","register_pk":"108611","name":"笑亀酒造造蔵","kana":"しょうきしゅぞうつくりぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県塩尻市大字塩尻町字町141-1他","lat":36.10329489,"lng":137.974304,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積1011㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0346","desc":"敷地の南半を占める大型土蔵。桁行３８ｍ梁間１６ｍ、土蔵造２階建、切妻造で、置屋根式の桟瓦葺とし、北・西面に梁間６ｍ前後の広い下屋を張り出す。南・東面の１、２階に窓を規則的に配し、リズム感を与える。周辺環境の中において、際立った量感を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007629"},{"id":"00007627","register_sub_id":"101","register_pk":"108609","name":"笑亀酒造店舗兼主屋","kana":"しょうきしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県塩尻市大字塩尻町字町141-1他","lat":36.103703,"lng":137.974472,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積250㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0344","desc":"旧中山道に北面して建つ。桁行１９ｍ梁間１１ｍ規模の木造２階建、切妻造桟瓦葺。１階外壁の両端を海鼠壁とし、庇上に波頭紋の役物瓦をあしらう。また中央の玄関両側にはスクラッチタイルを貼り、明治と昭和初めの意匠を融合した、重厚で特徴的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007627"},{"id":"00002035","register_sub_id":"101","register_pk":"103025","name":"巣山家住宅主屋","kana":"すやまけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県塩尻市大字木曽平沢字西町1561-1","lat":35.97926628,"lng":137.83019986,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積143㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"20 － 0089","desc":"木曽路にある平沢は奈良井宿の北に続く集落で，巣山家は代々漆器製造に携わってきた。主屋は通りに面した平入・２階建で，棟札より昭和８年の上棟である。正面は出桁で２階を前に持ち出し，両端に袖壁を設けるなど，伝統的なつくりをよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002035"},{"id":"00002037","register_sub_id":"101","register_pk":"103027","name":"巣山家住宅西土蔵","kana":"すやまけじゅうたくにしどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県塩尻市大字木曽平沢字西町1561-1","lat":35.97939852,"lng":137.83012869,"geo_status":"db","era":"明治32／昭和初期移築","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"20 － 0091","desc":"カミノクラと呼ばれ，もとは穀物を収蔵していたが，現在は工房に用いられている。棟木に明治３２年上棟の墨書があるが，昭和初期に現在地に移された。切妻造・２階建で，外壁は腰部を海鼠壁するが，上部の漆喰壁を上塗しないところは東土蔵と異なる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002037"},{"id":"00014484","register_sub_id":"101","register_pk":"513898","name":"セイコーエプソン創業記念館（旧大和工業事務所）","kana":"せいこーえぷそんそうぎょうきねんかん（だいわこうぎょうじむしょ）","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪市大和三丁目287-3","lat":36.05465,"lng":138.11534722,"geo_status":"db","era":"昭和20年／同43年頃増築、平成23年改修","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造2階建、瓦葺、建築面積193㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"20 - 0629","desc":"諏訪湖東岸に位置する時計部品製造会社の旧事務所。2階建寄棟造桟瓦葺で西に玄関ポーチを付す。外壁は下見板張とし、1、2階に連窓を多く配した開放的な外観。内部一階は西に寄せた片廊下、二階は中廊下式の平面。諏訪の時計製造の基点となった洋風事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014484"},{"id":"00001799","register_sub_id":"101","register_pk":"102789","name":"武重本家酒造及び武重家住宅一号蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくいちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27379665,"lng":138.33922542,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積505㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0063","desc":"武重家が酒造業を開始した明治元年創業時の建物で，のちに南屋根面を延ばした形で釜場を増築している。越屋根付，桟瓦葺，切妻屋根，土蔵造の長大な建屋になり，南屋根面に三つの切妻造の大型屋根窓を突き出す。事務室を含む中心的酒造施設になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001799"},{"id":"00001795","register_sub_id":"101","register_pk":"102785","name":"武重本家酒造及び武重家住宅井戸小屋","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくいどごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27365579,"lng":138.33884111,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、鉄板葺、建築面積8.4㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0068","desc":"西蔵の北方，離れ石積擁壁の下に位置する桁行１間半，梁行２間規模の東西棟，鉄板葺切妻屋根，真壁造の簡素な建屋で，創業来の丸井戸の覆屋となる。現在，井戸水は深井戸ポンプにより離れ石積擁壁上の煉瓦造水槽に送られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001795"},{"id":"00001806","register_sub_id":"101","register_pk":"102796","name":"武重本家酒造及び武重家住宅奥穀ビツ","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくおくこくびつ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27404948,"lng":138.33884566,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0071","desc":"前穀ビツの北妻面側から北方に延び，北端で東方に折れ曲がるＬ字型平面の穀ビツ。桟瓦葺，切妻造で，前穀ビツと同様な造りとなるが，折れ曲がりの部分は物置とする。原料貯蔵の施設であるとともに，造り酒屋の発展過程を物語る施設でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001806"},{"id":"00001807","register_sub_id":"101","register_pk":"102797","name":"武重本家酒造及び武重家住宅枯倉","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくかれぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県佐久市茂田井字用水尻2925-2","lat":36.27427362,"lng":138.33940842,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0072","desc":"屋敷地の北端に位置する桁行１７間，梁行４間規模のたちの高い建屋で，酒樽の用材を乾燥させておく施設。東西棟，桟瓦葺，切妻造で，内部を二層とし，南面全面に庇を差し掛ける。屋敷地拡張の過程を物語るとともに，造り酒屋としての構えの一構成要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001807"},{"id":"00001804","register_sub_id":"101","register_pk":"102794","name":"武重本家酒造及び武重家住宅旧細工小屋","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくきゅうさいくごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27374023,"lng":138.33876894,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0069","desc":"離れ北辺の石積擁壁の北に位置し，屋敷地西辺沿って建つ南北棟，桟瓦葺，切妻屋根，土蔵造の建屋で，東面に長く庇をさしだして平入とする。もと酒樽の製作場で，現在は資材置場となっている。造り酒屋の構えを構成する一要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001804"},{"id":"00001811","register_sub_id":"101","register_pk":"102801","name":"武重本家酒造及び武重家住宅旧精米所","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくきゅうせいまいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県佐久市茂田井字東町2188-3","lat":36.27333151,"lng":138.33844959,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0076","desc":"離れ敷地の斜向かい，水路が交わる地点の角地に旧中山道に大きな妻面を見せて建つ。桁行５間，梁行５間規模の南北棟，桟瓦葺，切妻屋根，真壁造のもと精米所で，水車を旧中山道沿いの水路に設置していたものとみられる。造り酒屋関連施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001811"},{"id":"00001803","register_sub_id":"101","register_pk":"102793","name":"武重本家酒造及び武重家住宅五号蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくごごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27401454,"lng":138.33900739,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積121㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0067","desc":"三号蔵の北に増築された桁行７間半規模の桟瓦葺，切妻屋根，土蔵造の酒蔵で，外観上は三号蔵と一体的につくり，さらに北へ糟場を増築している。東側面で四号蔵西妻面に連絡する。地棟下面の墨書から大正１１年３月上棟が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001803"},{"id":"00001801","register_sub_id":"101","register_pk":"102791","name":"武重本家酒造及び武重家住宅三号蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27384655,"lng":138.33899404,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積164㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0065","desc":"一号蔵・二号蔵の西に建つ南北棟，桟瓦葺，切妻屋根，土蔵造の仕込蔵で，北に同一梁間の五号蔵が延長されている。内部の間内柱は厚板材を組立て，ボルト締めした特異な仕様をとる。酒蔵建築における構造技法の多様性を知るうえで興味深い事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001801"},{"id":"00001808","register_sub_id":"101","register_pk":"102798","name":"武重本家酒造及び武重家住宅炭小屋","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくすみごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県佐久市茂田井字東町2177-1","lat":36.27389074,"lng":138.33966021,"geo_status":"db","era":"江戸後期／明治42移築改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0073","desc":"二号蔵の東方，道路を隔てた敷地に建つ。道路に妻面を見せている木造２階建，桁行２間半梁行６間の真壁造建屋に桁行２間半梁行３間半の下見板張りの平屋を南に棟を直交させて張り出す。住宅主屋の改築の際に旧主屋の一部を移築したものと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001808"},{"id":"00001800","register_sub_id":"101","register_pk":"102790","name":"武重本家酒造及び武重家住宅二号蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179他","lat":36.27387896,"lng":138.33923091,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積244㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0064","desc":"一号蔵の北方背後に，一号蔵と並列して建つ。東西棟，桟瓦葺，切妻屋根，土蔵造の仕込蔵で，一号蔵との間の西寄りに階段室，東端に洋風仕様の検査室を設ける。階上の東側を麹室に充てる。造り酒屋としての発展を物語る建物のひとつになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001800"},{"id":"00001805","register_sub_id":"101","register_pk":"102795","name":"武重本家酒造及び武重家住宅前穀ビツ","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくまえこくびつ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27397575,"lng":138.33882042,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0070","desc":"旧細工小屋の北方，屋敷地西辺に沿って建つ桟瓦葺，切妻造の細長い建屋。東面は出桁の造りとし，前面に低い切目縁を付ける。梁行１間で，片開戸口５戸前と横板を１２段に落込んだ戸口８戸前から成る。造り酒屋の原料貯蔵の様子を伝える施設として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001805"},{"id":"00001791","register_sub_id":"101","register_pk":"102781","name":"武重本家酒造及び武重家住宅もみ蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくもみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県佐久市茂田井字前田2140-2","lat":36.27302575,"lng":138.33903911,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0075","desc":"南蔵の南方に位置し，旧中山道に向かう道路に東妻面を見せて建つ東西棟，桟瓦葺，切妻屋根，置屋根形式の土蔵。桁行４間，梁行２間半の規模で，北面に下屋を差し掛けて蔵前をつくる。南蔵と同様に腰を押縁下見として旧中山道に向かう街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001791"},{"id":"00001802","register_sub_id":"101","register_pk":"102792","name":"武重本家酒造及び武重家住宅四号蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくよんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179他","lat":36.27399782,"lng":138.33923646,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積185㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0066","desc":"二号蔵の北方背後に並び建つ東西棟，桟瓦葺，切妻屋根，土蔵造の仕込蔵で，桁行１２間半，梁行４間半の規模を有し，一号蔵・二号蔵と同様に，二号蔵との間に階段室を納める。地棟下面の墨書により大正６年４月３０日の上棟が明らか。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001802"},{"id":"00010294","register_sub_id":"101","register_pk":"199067","name":"長野銘醸粕蔵","kana":"ながのめいじょうかすぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1他","lat":36.516834,"lng":138.075672,"geo_status":"db","era":"江戸末期／明治中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積67㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0471","desc":"敷地中央、酒蔵の北方に南北棟で建つ。桁行一一メートル梁間六・一メートル、土蔵造平屋建で、内部では酒粕の熟成を行っている。外壁は中塗仕上げとし、西面は腰に下見板を張る。もと南北に二棟であったものを、明治中期に壁を撤去し一体化したと考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010294"},{"id":"00010293","register_sub_id":"101","register_pk":"199066","name":"長野銘醸米蔵","kana":"ながのめいじょうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-5他","lat":36.516668,"lng":138.075352,"geo_status":"db","era":"江戸末期／大正5年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、鉄板葺、建築面積149㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0470","desc":"敷地中央、酒蔵の西方に南北棟で建つ土蔵造平屋建。玄米や精米後の白米を貯蔵していた蔵で、古絵図から明治中期には南に水車小屋を併設してここで精米を行っていたと考えられる。現在は床を張らないが、大引の痕跡が確認できる。酒造工程の一端を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010293"},{"id":"00010290","register_sub_id":"101","register_pk":"199063","name":"長野銘醸酒蔵","kana":"ながのめいじょうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-5","lat":36.516549,"lng":138.075571,"geo_status":"db","era":"江戸末期／明治期・大正期・昭和20年・昭和42年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積529㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0467","desc":"敷地中央に南北棟で建つ。土蔵造二階建で、平面は大きく南北に分けられる。北半では洗米と絞り、南半では仕込みが行われる。二階はもと麹室や酒母室として使われ、酒造神である松尾社を祀る。酒造場の中心建物となる大型土蔵で、杜氏の営みを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010290"},{"id":"00010289","register_sub_id":"101","register_pk":"199062","name":"長野銘醸事務所","kana":"ながのめいじょうじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県千曲市大字八幡字中原272-5他","lat":36.516877,"lng":138.075842,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積198㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0466","desc":"敷地東寄りに南面して建つ木造二階建で、正面に起りのある切妻破風の式台を構える。一階は事務所や店舗などを配する。二階の内壁は鼠漆喰仕上げを基本とし、室境に筬欄間を入れ、大振りなトコにケヤキの一枚板を使うなど、贅沢な造作になる近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010289"},{"id":"00010291","register_sub_id":"101","register_pk":"199064","name":"長野銘醸貯蔵蔵","kana":"ながのめいじょうちょぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-5","lat":36.516572,"lng":138.075833,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積68㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0468","desc":"酒蔵の東方に南北棟で建ち、桁行九・七メートル梁間七・〇メートル、土蔵造平屋建である。登梁形式の小屋組を駆使して建ちの高い空間を実現し、外観は二層に見せる。たたき土間の内部には清酒の貯蔵タンクを並べる。作業庭に面し、酒造場の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010291"},{"id":"00010300","register_sub_id":"101","register_pk":"199073","name":"長野銘醸長屋門","kana":"ながのめいじょうながやもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1","lat":36.51718765,"lng":138.07565004,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0477","desc":"敷地北辺東寄りに建ち、北国西脇往還に開かれた門。西半を門、東半を居室とし、かつては居室に門番が詰めたという。土蔵造二階建で、門の正面及び居室部分を漆喰塗仕上げとし、腰に下見板を張る。東土蔵とともに通り沿いの歴史的景観をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010300"},{"id":"00010298","register_sub_id":"101","register_pk":"199071","name":"長野銘醸西土蔵","kana":"ながのめいじょうにしどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1","lat":36.51706,"lng":138.075268,"geo_status":"db","era":"江戸末期／大正15年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0475","desc":"敷地北辺西寄り、北国西脇往還に面して建つ土蔵造二階建。外壁漆喰塗仕上げで水切と軒蛇腹を廻らし、通り沿いは腰を簓子下見板張とする。かつて旧主屋の座敷部が隣接して建っていた頃から家財道具を納めるための蔵として使われており、屋敷地の変遷を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010298"},{"id":"00010296","register_sub_id":"101","register_pk":"199069","name":"長野銘醸西納屋","kana":"ながのめいじょうにしなや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1他","lat":36.516903,"lng":138.075647,"geo_status":"db","era":"江戸末期／明治30年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0473","desc":"敷地中央に位置し、粕蔵の北方に接続して建つ。長屋門から訪れた際に正面に位置する建物で、かつては店舗として使われたという。土蔵造平屋建で、外壁は中塗仕上げと簓子下見板張で整え、内部は床板張とする。南に連なる粕蔵とともに酒造場の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010296"},{"id":"00010297","register_sub_id":"101","register_pk":"199070","name":"長野銘醸東土蔵","kana":"ながのめいじょうひがしどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1","lat":36.517132,"lng":138.07556,"geo_status":"db","era":"江戸末期／大正15年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積30㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0474","desc":"敷地北辺、北国西脇往還に面して長屋門の西隣に建つ。桁行梁間とも五・五メートル、土蔵造平屋建で通り側を入母屋造とする。当初は大工小屋として使われ、酒蔵に使う木桶の修繕を行っていたとされる。通りに面して屋敷構えの景観をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010297"},{"id":"00010295","register_sub_id":"101","register_pk":"199068","name":"長野銘醸東納屋","kana":"ながのめいじょうひがしなや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県千曲市大字八幡字中原274他","lat":36.516801,"lng":138.076095,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積87㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0472","desc":"敷地東辺中央に南北棟で建つ。土蔵造二階建で西面に吹放しの下屋を設ける。北半を物置、南半を居室とするが、かつて物置は味噌部屋、居室部は隠居部屋もしくは女中部屋として使われたという。小屋は他と異なり洋小屋である。敷地東面の景観を引き締める土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010295"},{"id":"00010299","register_sub_id":"101","register_pk":"199072","name":"長野銘醸文庫蔵","kana":"ながのめいじょうぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1","lat":36.516939,"lng":138.075146,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0476","desc":"敷地の北西に位置し、庭部分に面して南北棟で建つ。土蔵造二階建で外壁を黒漆喰で仕上げ、水切と鉢巻を廻らす。東面の戸口のほか小窓を穿つが、比較的閉鎖的な外観とする。掛子塗を施した観音開の扉や窓庇の持送りなどに、高い左官技術を見せる家財蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010299"},{"id":"00010292","register_sub_id":"101","register_pk":"199065","name":"長野銘醸南蔵","kana":"ながのめいじょうみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県千曲市大字八幡字中原275-1他","lat":36.516382,"lng":138.075914,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積298㎡、煉瓦造煙突付","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0469","desc":"敷地南東方、貯蔵蔵の東に建つ。煉瓦造の煙突を囲むように矩折の平面を持つ土蔵造二階建で、屋根は置き屋根式である。丸太材の柱や梁を用いた和小屋と登梁形式を併用して大スパンを実現する。当初は瓶詰の工程を担った土蔵で、近代の酒造業の発展を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010292"},{"id":"00009165","register_sub_id":"101","register_pk":"164718","name":"東飯田酒造店酒蔵","kana":"ひがしいいだしゅぞうてんさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市篠ノ井小松原1724","lat":36.62010707,"lng":138.13286862,"geo_status":"db","era":"明治6年","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び鉄板葺、建築面積357㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地北辺に建つ。桁行35.0メートル梁間9.7メートル、土蔵造平屋1部2階建、切妻造妻入桟瓦葺及び鉄板葺で、東妻の出入口上部に虫籠窓を穿つ。内部は貯蔵蔵、舟場、酛部屋を備える。通り沿いにのびる大規模な土蔵で、犀川畔の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009165"},{"id":"00009167","register_sub_id":"101","register_pk":"164720","name":"東飯田酒造店漬物蔵","kana":"ひがしいいだしゅぞうてんつけものぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井小松原1724","lat":36.61978584,"lng":138.1330566,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"土蔵の西側に並び建ち、桁行5.4メートル梁間3.6メートル、土蔵造2階建、切妻造桟瓦葺で、北面に下屋を設ける。外壁は漆喰塗で、扉廻りを黒漆喰で縁取り、軒裏は波形に塗籠めるなど丁寧な左官仕事になる。酒蔵とともに、創業期の様相を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009167"},{"id":"00009166","register_sub_id":"101","register_pk":"164719","name":"東飯田酒造店土蔵","kana":"ひがしいいだしゅぞうてんどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市篠ノ井小松原1724","lat":36.61978108,"lng":138.13315654,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積77㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"松の間の南側に北面して建つ。桁行10.9メートル梁間5.5メートル、土蔵造1部2階建、切妻造桟瓦葺で、北面に下屋を設ける。内部は東西に2分し、各々出入口を設けて米蔵とした。軸部は丸太柱を使い、下階床を煉瓦敷とする。造酒屋の施設構成を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009166"},{"id":"00003544","register_sub_id":"101","register_pk":"104534","name":"ふれあい館まゆぐら（旧田尻製糸）","kana":"ふれあいかんまゆぐら（きゅうたじりせいし）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂387-2","lat":36.65468593,"lng":138.30968724,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造3階建、瓦葺、建築面積145㎡","structure_material":"土蔵造3階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0148","desc":"地元の田尻製糸の繭蔵として建てられた３階建の土蔵で，現在地より約１８０ｍ南東の地から曳家し，体験や展示等の施設として活用されている。切妻造，桟瓦葺，桁行１０間と長大な規模で，外壁白漆喰塗，各面とも整然と各階の窓を並べた繭蔵らしい外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003544"},{"id":"00005149","register_sub_id":"101","register_pk":"106139","name":"松下家住宅作業所","kana":"まつしたけじゅうたくさぎょうしょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市松代町松代946","lat":36.56389766,"lng":138.20304987,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、鉄板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0217","desc":"敷地北側に位置し，主屋の背後に建つ。桁行８間半，梁間２間規模の木造平屋建で，鉄板葺の片流屋根を置く。北側外壁は外構を兼ね，南側は庭に向かい全面開口部となる。染物業の作業所として使われ，染物業を営む商家の屋敷の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005149"},{"id":"00008997","register_sub_id":"101","register_pk":"162357","name":"丸高蔵鰍沢蔵","kana":"まるたかぐらかじかざわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県諏訪市高島1-2952-1","lat":36.04123753,"lng":138.11327056,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵2階建、鉄板葺、建築面積272㎡","structure_material":"土蔵2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0394","desc":"吉沢蔵の南隣、通り沿いに建つ。桁行２６ｍ梁間１０ｍ、土蔵造二階建、切妻造鉄板葺で、東面に出入口を開く。外壁は漆喰仕上げで、鉢巻下まで高く竪板を張る。北から店舗、吉沢蔵と並び建ち、歴史的な景観を残す通りの主要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008997"},{"id":"00008996","register_sub_id":"101","register_pk":"162356","name":"丸高蔵吉沢蔵","kana":"まるたかぐらきっさわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県諏訪市高島1-2952-1","lat":36.04154955,"lng":138.1134143,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、鉄板葺、建築面積710㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0393","desc":"店舗の南隣に建つ。桁行３１ｍ梁間１０ｍ、土蔵造二階建、南北棟の寄棟造鉄板葺である。東面に出入口を開き、外壁は漆喰仕上げで腰高に竪板を張る。正背面に下屋を張り出し、北面に平屋建の棟を付属する。老舗醸造所の風格を示す大規模な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008996"},{"id":"00008995","register_sub_id":"101","register_pk":"162355","name":"丸高蔵店舗","kana":"まるたかぐらてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県諏訪市高島1-2952-1","lat":36.04180897,"lng":138.11351947,"geo_status":"db","era":"大正前期／平成18年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、鉄板葺、建築面積262㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0392","desc":"上諏訪市街の通りに西面して建つ。桁行１０ｍ梁間１６ｍ、木造二階建、切妻造妻入鉄板葺で、伝統的な民家形式である本棟造の建物である。一階の正背面に深い庇を設け、二階の中央に出窓を設けるなど、本棟造独特の陰影のある外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008995"},{"id":"00003236","register_sub_id":"101","register_pk":"104226","name":"三原屋商店中蔵","kana":"みはらやしょうてんなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市大字長野字桜枝町879-1","lat":36.65845467,"lng":138.18342853,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積67㎡","structure_material":"土蔵造3階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0123","desc":"店舗南方に位置し，東面を「うちわや小路」に見せて建つ。桁行５間梁間４間規模の２階建土蔵に桁行３間半梁間２間，東西棟，寄棟造の３階部を載せ，南面で東蔵に連絡する。店舗裏口部の海鼠壁東面に連なり，小路沿い土蔵群景観に欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003236"},{"id":"00003239","register_sub_id":"101","register_pk":"104229","name":"三原屋商店西蔵","kana":"みはらやしょうてんにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市大字長野字御殿1151-1","lat":36.65821067,"lng":138.18327257,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0126","desc":"南蔵の西方，屋敷地西辺沿いに位置し南北棟で建つ。桁行６間梁間２間半規模，桟瓦葺，切妻造の２階建土蔵で，平側東面のほぼ中央に出入口をとり，２階には南蔵との連絡口を設ける。醸造場南部土蔵群を構成する主要素のひとつで，味噌貯蔵庫として使用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003239"},{"id":"00003237","register_sub_id":"101","register_pk":"104227","name":"三原屋商店東蔵","kana":"みはらやしょうてんひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市大字長野字桜枝町879-1","lat":36.65825233,"lng":138.18338767,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積140㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0124","desc":"中蔵の南面に接して南北棟で建つ。桁行１０間梁間４間規模，桟瓦葺，切妻造の長大な２階建醤油醸造蔵で，東面は中蔵と同様に腰を簓子下見とし，南妻面には重厚な観音扉をもつ窓を左右対称に配置する。小路沿い土蔵群景観の構成要素中最も存在感のある土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003237"},{"id":"00003238","register_sub_id":"101","register_pk":"104228","name":"三原屋商店南蔵","kana":"みはらやしょうてんみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市大字長野字桜枝町879-1・字御殿1151-1","lat":36.65822486,"lng":138.18332591,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0125","desc":"屋敷地南方，住居部との境界際に位置し，東蔵と西蔵に挟まれて建つ。桁行５間梁間２間半規模，東西棟，桟瓦葺，切妻造のたちの低い２階建土蔵で，もとは東半を麹室に充てる。平側南面のほぼ中央に出入口を設け，中庭側への物資の搬入にも重要な役割を果たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003238"},{"id":"00006535","register_sub_id":"101","register_pk":"107518","name":"蒲酒造場仕込蔵一","kana":"かばしゅぞうじょうしこみぐらいち","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町6-6","lat":36.235146,"lng":137.186951,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積139㎡","structure_material":"土蔵造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0133","desc":"屋敷地の北西方に位置し，瀬戸川用水沿いに東西棟で建つ。桁行７間，梁間６間規模，切妻造，鉄板葺の平屋建土蔵で，用水側の北面に３箇所の小窓のほか，東寄りに搬出入用の戸口を開ける。瀬戸川用水の流れと白壁土蔵群がつくる景観の構成要素のひとつになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006535"},{"id":"00006533","register_sub_id":"101","register_pk":"107516","name":"蒲酒造場袖蔵","kana":"かばしゅぞうじょうそでぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町6-6","lat":36.23489122,"lng":137.18711906,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積106㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0131","desc":"屋敷地の南東隅に位置し東西棟で建つ。桁行４間，梁行８間規模，切妻造，鉄板葺の２階建酒蔵で，主屋土間に面する西面北寄りに戸口を開ける。押縁下見板張に白漆喰塗の外観は維持管理が極めて良好で，主屋とともに壱之町通りのシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006533"},{"id":"00006189","register_sub_id":"101","register_pk":"107173","name":"菊川酒造一号・二号倉庫","kana":"きくかわしゅぞういちごう・にごうそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-543","lat":35.404125,"lng":136.93718,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積118㎡","structure_material":"土蔵造2階一部平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0113","desc":"敷地東端に南北棟で建ち，桁行１０間半，梁間３間の規模で，土蔵造２階一部平屋建，切妻造，桟瓦葺である。北側の一号倉庫は小屋組にキングポストトラスを用い，二号倉庫は登梁の和小屋を用いる。外壁は漆喰塗で，下半を下見板で養生し，酒造場の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006189"},{"id":"00006184","register_sub_id":"101","register_pk":"107168","name":"菊川酒造本蔵","kana":"きくかわしゅぞうほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-543","lat":35.404503,"lng":136.936722,"geo_status":"db","era":"大正9頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積335㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0111","desc":"旧鵜沼宿の中山道に面して建つ酒造蔵である。桁行１１間半，梁間７間半の規模で，土蔵造２階建，切妻造，桟瓦葺とする。南面に下屋を張り出す。外壁は漆喰塗で，外側に鉄板を張る。和小屋で登梁を使用する。規模が大きく，大きな梁を用い，架構技術に優れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006184"},{"id":"00009962","register_sub_id":"101","register_pk":"196109","name":"玉泉堂酒造北酒蔵","kana":"ぎょくせんどうしゅぞうきたさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126他","lat":35.30836112,"lng":136.55643272,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積246㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0227","desc":"南蔵と接続して、東西棟で建つ。桁行一〇間梁間六間、土蔵造二階建である。もとは仕込蔵として酒の仕込みを行っていた。二階にはもと麹室があり、別棟で蒸した米を二階で広げて温度調整を行っていた。樽を多数並べるため、大空間を実現した大型の蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009962"},{"id":"00009963","register_sub_id":"101","register_pk":"196110","name":"玉泉堂酒造検査室及び税務事務室","kana":"ぎょくせんどうしゅぞうけんさしつおよびぜいむじむしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126他","lat":35.30839615,"lng":136.55656862,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積43㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0228","desc":"北酒蔵の北正面東端に接続して建ち、南側を検査室、北側を税務事務室とする。検査室内部は真壁造、棹縁天井の和風とするのに対し、税務事務室は天井まで漆喰塗仕上げとして天井蛇腹を廻らし、腰を擬石塗とする洋風意匠である。当時の酒税事務を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009963"},{"id":"00009959","register_sub_id":"101","register_pk":"196106","name":"玉泉堂酒造小売り場","kana":"ぎょくせんどうしゅぞうこうりば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126他","lat":35.30853441,"lng":136.5567439,"geo_status":"db","era":"大正13／昭和中期改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0224","desc":"主屋の東側に並び建つ間口五・八メートルの二階建建物で、正面二階を黒漆喰塗として店舗兼主屋と調和させる。一階北半を小売り場とし、南半を物置とする。軸部は柱を半間毎に建て、隅には火打梁を設ける。戦前期の酒類小売りの様相を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009959"},{"id":"00009964","register_sub_id":"101","register_pk":"196111","name":"玉泉堂酒造洗米所","kana":"ぎょくせんどうしゅぞうせんまいじょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126他","lat":35.30848717,"lng":136.55645796,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0229","desc":"主屋背面、北酒蔵の北西側下屋の先に位置する。切妻造の比較的小規模な建物で、もとは洗米と蒸米を行った。南面と東面には壁を設けず開放的にし、キングポストトラス組の陸梁の上にベルトを掛けたプーリーが残る。酒類の製造工程を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009964"},{"id":"00009958","register_sub_id":"101","register_pk":"196105","name":"玉泉堂酒造店舗兼主屋","kana":"ぎょくせんどうしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126","lat":35.30859769,"lng":136.55660813,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積262㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0223","desc":"街道沿いに北面して建つ。間口一九メートルを測る大型の店舗兼主屋で、東寄りに土間を通し、西側に三室を三列に並べる。正面は一階に出格子をたて、二階は黒漆喰塗で柱形を表し、格子窓を並べ、両端に袖壁を設ける。外観や軸部構成ともに重厚で良質な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009958"},{"id":"00009960","register_sub_id":"101","register_pk":"196107","name":"玉泉堂酒造土蔵","kana":"ぎょくせんどうしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126","lat":35.30840235,"lng":136.55666284,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0225","desc":"主屋の東背面に位置する。内向きの家財道具のための蔵で、南北棟で北を正面とする。基礎は切石を三段積む。外壁は黒漆喰で塗り込め、正面出入口扉脇の腰壁を蜀江文様風の意匠に仕上げ、正面扉や二階の窓は掛子塗戸とするなど、高い左官技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009960"},{"id":"00009961","register_sub_id":"101","register_pk":"196108","name":"玉泉堂酒造南酒蔵","kana":"ぎょくせんどうしゅぞうみなみさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126他","lat":35.30822157,"lng":136.55628538,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積308㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0226","desc":"敷地南側に南北棟で建ち、北妻面は北酒蔵と接続する。桁行一二間梁間六間、土蔵造二階建である。貯蔵蔵で、もとは北酒蔵で作られた醪を、酒粕と清酒に分け、精製して熟成させ、瓶詰めする作業が行われていた。二重梁の和小屋を架けて広い梁間を確保する大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009961"},{"id":"00010302","register_sub_id":"101","register_pk":"199075","name":"日下部味噌醤油醸造煉瓦館","kana":"くさかべみそしょうゆじょうぞうれんがかん","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県高山市上一之町93-1","lat":36.141094,"lng":137.261097,"geo_status":"db","era":"大正11年／昭和50年頃・平成2年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積86㎡","structure_material":"煉瓦造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"21-0236","desc":"醤油醸造所の醤油蔵として建てられた。煉瓦造二階建、妻入りで、軒蛇腹を廻らしてデンティルを飾り、西正面にコーニスを設け、水平アーチ窓を三所穿ち鉄扉を開く。町家主体の街並み景観に変化を与える存在で、市内で数少ない煉瓦造建築としても価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010302"},{"id":"00007036","register_sub_id":"101","register_pk":"108018","name":"小町酒造通用門","kana":"こまちしゅぞうつうようもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-15","lat":35.4221053,"lng":136.86183893,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造、瓦葺、間口4.1m","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0164","desc":"敷地東面の中央に位置し、北は本蔵、南は便所に取り付く。両下造桟瓦葺。間口４．１ｍで、中央戸口２．３ｍに両開板戸をたて、南に袖塀、北に潜りを設ける。主柱は小平柱で、腕木により軒を持ち出す。大きく開く入八双金物が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007036"},{"id":"00007032","register_sub_id":"101","register_pk":"108014","name":"小町酒造店舗兼主屋","kana":"こまちしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-15","lat":35.42205793,"lng":136.86174635,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0160","desc":"３方を道路に囲まれた敷地南側に南面して建つ。木造２階建、切妻造桟瓦葺とし、建築面積は１５４㎡。東側を土間の店舗などとし、西側を４間取の床上部とする。外壁は黒漆喰仕上げとし、軒は出桁造。重厚な外観に杉玉を飾り、酒造業としての風格を醸し出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007032"},{"id":"00007034","register_sub_id":"101","register_pk":"108016","name":"小町酒造土蔵","kana":"こまちしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-15","lat":35.421986,"lng":136.861801,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0162","desc":"敷地南東隅に通りに面して建ち、店舗兼主屋に接する。土蔵造２階建、切妻造桟瓦葺で、桁行６．６ｍ梁間３．８ｍ。丸石積基礎とし、外壁は漆喰仕上げで黒塗の板を張る。南側各階の窓に持送り付の庇を付け、外観に変化を与える。落ち着きのある街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007034"},{"id":"00007033","register_sub_id":"101","register_pk":"108015","name":"小町酒造離れ","kana":"こまちしゅぞうはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-15","lat":35.42203903,"lng":136.86157438,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0161","desc":"敷地の南西、店舗兼主屋の西側に建つ。木造平屋建、入母屋造桟瓦葺で、南北に８畳２室を並べ、東に畳廊下、南・北に榑縁、３方に落縁を設ける。主座敷はトコと違棚、付書院を構え、その南を庭園とする。数寄屋風意匠を採り入れた近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007033"},{"id":"00007035","register_sub_id":"101","register_pk":"108017","name":"小町酒造門及び塀","kana":"こまちしゅぞうもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-15","lat":35.42193556,"lng":136.86159073,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口1.2m 塀 木造、瓦葺、延長21m","structure_material":"門 木造","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0163","desc":"店舗兼主屋から離れまで、庭園を囲むようにコの字状に配された総延長２１ｍの塀。東面には切妻造桟瓦葺の腕木門を構える。丸石を亀甲状に積み石垣とし、通り側には黒漆喰に腰板張、庭園側を弁柄色の色壁とする。丸石積が印象的な屋敷構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007035"},{"id":"00011135","register_sub_id":"101","register_pk":"205242","name":"天領酒造店舗兼主屋","kana":"てんりょうしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県下呂市萩原町萩原字町頭1289-1","lat":35.875935,"lng":137.209079,"geo_status":"db","era":"明治44頃／大正4頃増築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積237㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"21 - 0243","desc":"益田街道に面して建つ。店舗兼主屋は明治四四年の大火後に再建された。街路側南半を土間のチョウバとし、その奥にトオリドウジ（土間廊下）を通して居室を配する一方、オモテ北半の北東側にもオクノマ、ブツマを張出すなど、当地方の標準的な平面になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011135"},{"id":"00009954","register_sub_id":"101","register_pk":"196101","name":"美濃窯業株式会社瑞浪工場角型煙突","kana":"みのようぎょうかぶしきがいしゃみずなみこうじょうかくがたえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県瑞浪市寺河戸町字上門田921-4他","lat":35.36588634,"lng":137.24954597,"geo_status":"db","era":"大正9／昭和7・平成17改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造、高さ26m","structure_material":"煉瓦造","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0219","desc":"煉瓦造、イギリス積で、基部の平面は二・三メートル角の正方形とし、高さは二六メートルを測る。腰部に装飾的な帯状部を設け、現在は鉄製アングル材で補強している。窯業が盛んな東濃地方に残るものとして最大級の煉瓦煙突であり、当地の近代産業史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009954"},{"id":"00010596","register_sub_id":"101","register_pk":"201170","name":"美濃窯業株式会社瑞浪工場丸型煙突","kana":"みのようぎょうかぶしきがいしゃみずなみこうじょうまるがたえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県瑞浪市寺河戸町字上門田924-1","lat":35.365371,"lng":137.249942,"geo_status":"db","era":"昭和10年／昭和62年・平成16年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"煉瓦造、高さ24m","structure_material":"煉瓦造","registered":"2015.08.04(平成27.08.04)","register_no":"21－0238","desc":"工場建物の南東寄りに位置する。小口積の煉瓦造で、基部平面は直径三メートルの円形とし、高さは二四メートルを測る。現在は鉄製アングル材で補強される。窯業が盛んな当地の歴史を物語る遺構として価値があり、同工場の角形煙突とともにランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010596"},{"id":"00008459","register_sub_id":"101","register_pk":"134855","name":"三輪酒造北蔵","kana":"みわしゅぞうきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県大垣市南切石町1-45-1","lat":35.35498842,"lng":136.6104572,"geo_status":"db","era":"明治21年","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積398㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"21 － 0192","desc":"運河を埋め立てた街路の南に占める敷地の中央南寄りに位置する。桁行二二メートル梁間一四メートル、南北棟の切妻造桟瓦葺の西側に、梁間四・六メートルの招屋根を付ける。土蔵造二階建で、外壁は下見板張、内壁は漆喰仕上げとする。大規模な醸造蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008459"},{"id":"00008460","register_sub_id":"101","register_pk":"134856","name":"三輪酒造南蔵","kana":"みわしゅぞうみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県大垣市南切石町1-45-1","lat":35.35478029,"lng":136.6105345,"geo_status":"db","era":"明治20年","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積361㎡","structure_material":"土蔵造3階建","registered":"2011.01.26(平成23.01.26)","register_no":"21 － 0193","desc":"敷地南端、小路に面する。東西棟で、棟高や梁間等が異なる三部分に分かれる。総桁行三三メートル梁間最大一四メートル、土蔵造三階建で、西端部のみ二階建。切妻造桟瓦葺とし、川石を積み上げた基礎上、鉢巻まで高く下見板を張り、重厚な街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008460"},{"id":"00004972","register_sub_id":"101","register_pk":"105962","name":"渡邉家住宅酒蔵","kana":"わたなべけじゅうたくさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町7-3","lat":36.23556276,"lng":137.18624021,"geo_status":"db","era":"明治14","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積133㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"21 － 0065","desc":"敷地後方北端の瀬戸川沿いにあり，古川を特長づける土蔵群の町並景観の構成要素である。土蔵造２階建で，南面１階に観音開扉を構え，東面と南面に窓を設ける。小屋は登梁式，屋根は置屋根式鉄板葺で，外壁は漆喰塗とする。造酒屋の屋敷構成に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004972"},{"id":"00009965","register_sub_id":"101","register_pk":"196112","name":"旧片岡醸造所酒蔵","kana":"きゅうかたおかじょうぞうしょさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県島田市横岡新田字新宿193","lat":34.84517787,"lng":138.11452343,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積397㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"22 － 0193","desc":"大井川右岸の敷地後方に東西棟で建ち、土蔵造二階建、桁行二八メートル梁間一五メートル、寄棟造桟瓦葺である。外壁は漆喰塗で各階の上部に窓を並べる。主構造は側柱と三本の丸太の独立柱で構成し、広大な内部空間をつくる。造酒屋の盛期を伝える大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009965"},{"id":"00009608","register_sub_id":"101","register_pk":"194604","name":"旧丸四織物合名会社倉庫（ドルチェ倉庫）","kana":"きゅうまるしおりものごうめいがいしゃそうこ（どるちぇそうこ）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県磐田市福田字村前東4447-2他","lat":34.67502148,"lng":137.87889028,"geo_status":"db","era":"昭和前期／平成9改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、建築面積129㎡","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"22 － 0192","desc":"敷地の南東に建つもと織物工場の木造倉庫。切妻造桟瓦葺で、北面に下屋を設けて中央を入口とする。外壁は下見板張で、東、南、西の各面二箇所に両開窓、両妻に高窓を開く。小屋裏二階の床は撤去し、二重梁和小屋の小屋組を現す。地場産業の名残を伝える倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009608"},{"id":"00014833","register_sub_id":"101","register_pk":"519093","name":"匂阪家住宅（鶴屋本店）隠居部屋","kana":"さぎさかけじゅうたく（つるやほんてん）いんきょべや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県磐田市見付3497","lat":34.72690556,"lng":137.85553889,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"22 - 0328","desc":"見付宿の中ほど、通りに東面して建つ味噌醤油醸造元の隠居屋。北側に文庫蔵が接続する。二階建桟瓦葺の南北棟で東面南寄りに玄関を設ける。内部は上下階とも続き間座敷とし各階南西に縁を廻らす。座敷は平書院の下地窓など瀟洒な意匠を取入れた近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014833"},{"id":"00014834","register_sub_id":"101","register_pk":"519094","name":"匂阪家住宅（鶴屋本店）文庫蔵","kana":"さぎさかけじゅうたく（つるやほんてん）ぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県磐田市見付3498","lat":34.72695,"lng":137.85550833,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造3階建、瓦葺、建築面積45㎡","structure_material":"木造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"22 - 0329","desc":"隠居部屋の北に接続して東西棟で建つ。土蔵造三階建切妻造桟瓦葺で、東面を戸口として下屋を付す。伊豆石の布積基礎に建ち、外壁漆喰塗で水切二段を付し、二、三階の両妻に窓を開け、掛子塗の扉を両開きとする。見付宿の歴史的な景観に寄与する三階建土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014834"},{"id":"00009607","register_sub_id":"101","register_pk":"194603","name":"寺田家住宅主屋（旧丸四織物合名会社事務所兼主屋）","kana":"てらだけじゅうたくしゅおく（きゅうまるしおりものごうめいがいしゃじむしょけんしゅおく）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県磐田市福田字村前東4447-2他","lat":34.67526894,"lng":137.87871658,"geo_status":"db","era":"昭和12／昭和42改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"22 － 0191","desc":"綿織物工場主の住宅で、木造二階建、切妻造桟瓦葺である。寄棟造の南東突出部は下見板張で、上下階に二つずつ並ぶ上下窓が外観を特徴づける。内部は一階南東室が洋室、一階八畳、二階一〇畳の座敷に座敷飾を備え、南面に広縁がつく。洋間付の良質な近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009607"},{"id":"00011506","register_sub_id":"101","register_pk":"210535","name":"明治屋醤油醸造所","kana":"めいじやしょうゆじょうぞうじょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市浜北区小松2276","lat":34.79055,"lng":137.77480889,"geo_status":"db","era":"明治前期／大正前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階一部平屋建、醪蔵部鉄筋コンクリート造平屋建、瓦葺一部銅板葺、建築面積774㎡","structure_material":"木造2階一部平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"22-0233","desc":"敷地東北寄りに建つ。南東隅部分が当初で、その後増築を繰り返して複雑な構成を取るが、東側街路寄りに香辛料倉庫・穀物倉庫、南方に圧搾等の機能を配し、北西側には鉄筋コンクリート造の醪蔵があり、中央部分に麹室を配する。醸造業の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011506"},{"id":"00011504","register_sub_id":"101","register_pk":"210533","name":"明治屋醤油店舗兼主屋","kana":"めいじやしょうゆてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市浜北区小松2276","lat":34.79027806,"lng":137.77467194,"geo_status":"db","era":"明治前期／大正6年増築、平成27年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"22-0231","desc":"浜松市街地の北方に位置する。敷地東寄りに街路に面して建ち、切妻造桟瓦葺の木造平屋建を二棟並べた構成をとるが、東棟は大正六年の増築。平面は三列構成となり、街路側は店舗、敷地内側は居室を配する。特徴的な構造をとる店舗兼主屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011504"},{"id":"00011505","register_sub_id":"101","register_pk":"210534","name":"明治屋醤油離れ","kana":"めいじやしょうゆはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市浜北区小松2276","lat":34.79023111,"lng":137.77452,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"22-0232","desc":"主屋の南西側に雁行して建つ。切妻造の二階建部分の東・南に下屋を張出し、北には玄関、西には浴室を張出す。一階は八畳座敷と六畳次の間の三方に広縁を廻らし、二階も八畳座敷、六畳次の間の二室構成とする。建ちの高い外観が特徴的な近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011505"},{"id":"00012377","register_sub_id":"101","register_pk":"531701","name":"愛知製鋼刈谷工場旧試作工場西棟（旧豊田自動織機製作所自動車部試作工場）","kana":"あいちせいこうかりやこうじょうきゅうしさくこうじょうにしとう（きゅうとよだじどうしょっきせいさくしょじどうしゃぶしさくこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県刈谷市豊田町三丁目6","lat":34.99086111,"lng":136.9977,"geo_status":"db","era":"昭和9年／昭和20年代改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積758㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"23-516","desc":"豊田自動織機製作所に建設された自動車の試作工場の西半部。東西棟の木造平屋建で、小屋組はキングポストトラス。外壁は亜鉛鉄板張で、内部の独立柱にも亜鉛鉄板を巻く。方杖を用いて柱と小屋組を緊結し、耐震性能を確保するため工夫がみられる工場建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012377"},{"id":"00012376","register_sub_id":"101","register_pk":"531700","name":"愛知製鋼刈谷工場旧試作工場東棟（旧豊田自動織機製作所自動車部試作工場）","kana":"あいちせいこうかりやこうじょうきゅうしさくこうじょうひがしとう（きゅうとよだじどうしょっきせいさくしょじどうしゃぶしさくこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県刈谷市豊田町三丁目6","lat":34.99076944,"lng":136.9982,"geo_status":"db","era":"昭和9年／昭和20年代改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積934㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"23-515","desc":"豊田自動織機製作所に建設された自動車の試作工場の東半部。東西棟の木造平屋建で、小屋組はキングポストトラス。内部は中央柱筋に独立柱が並んだ一つの空間とする。トヨタ自動車のＡ１型試作乗用車が誕生した工場として我が国の自動車産業史に名を残す建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012376"},{"id":"00004137","register_sub_id":"101","register_pk":"105127","name":"旭サナック本館（旧旭兵器製造本社事務棟）","kana":"あさひさなっくほんかん（きゅうあさひへいきせいぞうほんしゃじむとう）","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県尾張旭市旭前町新田洞5050","lat":35.217331,"lng":137.020401,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積338㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"23 － 0133","desc":"木造２階建で，屋根は寄棟造，鉄板葺。当初は外壁を下見板張としていたが，現状はモルタル吹付である。内部は１階を主に事務室とし，２階には応接間等を配するが，２階主要室は木部と漆喰による質の高い内装を持つ。洋風を基調とする事務所建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004137"},{"id":"00000215","register_sub_id":"101","register_pk":"101205","name":"窯のある広場・資料館（倒焔式角窯）","kana":"かまのあるひろば・しりょうかん（とうえんしきかくがま）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県常滑市奥栄町一丁目112","lat":34.88194628,"lng":136.8486342,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建，瓦葺，建築面積373㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"23 － 0006","desc":"煉瓦造の倒焔式角窯を含む、木造２階建の上屋である。昭和46年まで土管、焼酎瓶、クリンカタイル等を製造していたが、その後資料館として整備された。独特のテクスチャーを持つ角窯と、黒い外壁の上屋で、焼物の町常滑のシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000215"},{"id":"00000216","register_sub_id":"101","register_pk":"101206","name":"窯のある広場・資料館煙突","kana":"かまのあるひろば・しりょうかんえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県常滑市奥栄町一丁目112","lat":34.88186981,"lng":136.84855652,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造，高さ21m","structure_material":"煉瓦造","registered":"1997.06.12(平成9.06.12)","register_no":"23 － 0007","desc":"土管焼成用の窯に付属する煉瓦造の煙突である。根本の部分は2.2メートル四方であり、上部に向かってやや逓減する。かつては常滑市内に同様の煙突が数多くあったが、現在ではその多くが失われており、常滑市のランドマークの一つとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000216"},{"id":"00004982","register_sub_id":"101","register_pk":"105972","name":"甘強味淋工場","kana":"かんきょうみりんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県海部郡蟹江町城4-1","lat":35.13130593,"lng":136.79012156,"geo_status":"db","era":"明治10／明治39・大正2増築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積759㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"23 － 0206","desc":"敷地東にコの字型平面で建つ。北辺が古く，次に西辺が増築，これより東に延びた南辺が増築，現在の形となった。土蔵造２階建を基本とするが，一部煉瓦壁を用い，外壁の高い位置に窓を整然と並べる。伝統産業の発展過程を示す施設で，独特の景観を創っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004982"},{"id":"00011730","register_sub_id":"101","register_pk":"210746","name":"旧中七木綿本店北蔵","kana":"きゅうなかしちもめんほんてんきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28","lat":34.966809,"lng":136.865742,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積78㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"23 - 0500","desc":"敷地の西端で南蔵の北に建つ。桁行九・一メートル、梁間五・五メートル、切妻造桟瓦葺で、正面に南蔵から一連に続く蔵前を付ける。内部は一・二階とも一室とし、北面に窓を開く。南蔵とともに重厚な外観を見せ、街路からの景観を形成する大型の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011730"},{"id":"00011729","register_sub_id":"101","register_pk":"210745","name":"旧中七木綿本店作業所・寄宿舎","kana":"きゅうなかしちもめんほんてんさぎょうしょ・きしゅくしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28","lat":34.966662,"lng":136.865918,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積190㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"23 - 0499","desc":"主屋（旧事務所）の背後の敷地北側に建つ。平屋建の作業所と二階建の寄宿舎を東西に接続させる。作業所は、木綿製品を梱包する作業を行っていたが、黒漆喰塗の主屋と揃えた外観を持つ。寄宿舎は後に住居として転用されたが、二階には往時の姿をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011729"},{"id":"00011725","register_sub_id":"101","register_pk":"210741","name":"旧中七木綿本店主屋（旧事務所）","kana":"きゅうなかしちもめんほんてんしゅおく（きゅうじむしょ）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28-1","lat":34.966587,"lng":136.865775,"geo_status":"db","era":"大正3年／昭和20年移築","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0495","desc":"知多半島西海岸北部に位置する。木造二階建、入母屋造桟瓦葺。中央東寄りに玄関を開き、西に旧事務所を配置し、二階にはかつて接客のために用いられた二室を配す。やや起りのある屋根には屋号が入った鬼瓦を用い、外壁は黒漆喰塗とし、重厚な外観を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011725"},{"id":"00011727","register_sub_id":"101","register_pk":"210743","name":"旧中七木綿本店長屋門","kana":"きゅうなかしちもめんほんてんながやもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28-1","lat":34.966421,"lng":136.865777,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0497","desc":"敷地の南・東面を画す矩折れ平面の寄棟造桟瓦葺。東西棟は間口一九メートルでやや東寄りに門口を開き、両脇は納屋。南北棟は旧食事室や浴室、賄い部屋などを配し、社員の生活に必要な設備を備える。外壁は漆喰塗腰板張とし、重厚な表構えで街路景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011727"},{"id":"00011728","register_sub_id":"101","register_pk":"210744","name":"旧中七木綿本店塀","kana":"きゅうなかしちもめんほんてんへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28-1","lat":34.96648306,"lng":136.8659,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、延長6.2m","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0498","desc":"長屋門から敷地東面を画す。敷地の高低差に応じて、棟を三段に下げながら続く。下見板張の上部を漆喰塗とし、要所に格子窓を開く。切妻屋根上には屋号入りの鬼瓦を載せる。長屋門と一体となり、地域の歴史的景観を形成する塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011728"},{"id":"00011726","register_sub_id":"101","register_pk":"210742","name":"旧中七木綿本店南蔵","kana":"きゅうなかしちもめんほんてんみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28-1","lat":34.966731,"lng":136.865666,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積107㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0496","desc":"敷地の西端に東面する。桁行九・一メートル、梁間五・四メートル、切妻造桟瓦葺で、正面に奥行二間の蔵前を付ける。内部は中央北寄りに通し柱を立て、小屋は牛梁に登梁を架ける。外壁は鉢巻まで下見板を張り、二階南面のみ窓を開く。木綿製品を貯蔵するための蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011726"},{"id":"00013404","register_sub_id":"101","register_pk":"368489","name":"葛利毛織工業株式会社主屋","kana":"くずりけおりこうぎょうかぶしきがいしゃおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33523056,"lng":136.75968611,"geo_status":"db","era":"昭和24年頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積186㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0551","desc":"敷地南端中央の門を入って東側に建つ。木造二階建、寄棟造桟瓦葺で、東西棟の住居と南北棟の倉庫を、Ｌ字形に繋ぐ。外壁は下見板張、ペンキ塗仕上を基本とし、一階下屋部分は真壁、漆喰仕上、腰を竪板張とする。職住一体の工場施設の様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013404"},{"id":"00013407","register_sub_id":"101","register_pk":"368492","name":"葛利毛織工業株式会社旧浴場及び便所","kana":"くずりけおりこうぎょうかぶしきがいしゃきゅうよくじょうおよびべんじょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33536389,"lng":136.75969444,"geo_status":"db","era":"昭和30年頃／昭和30年代増築","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0554","desc":"工場の南東、男子寮の東に建つ、木造平屋建、切妻造桟瓦葺。外壁は漆喰塗仕上げで、腰はモルタル塗仕上とする。西側の浴場は、更に東西に分かれ、東を男性、西を女性の浴室とする。通路を挟んで東側に便所を南北に並べる。工場を構成するの附属施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013407"},{"id":"00013409","register_sub_id":"101","register_pk":"368494","name":"葛利毛織工業株式会社原糸倉庫","kana":"くずりけおりこうぎょうかぶしきがいしゃげんしそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33537222,"lng":136.75931111,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0556","desc":"敷地西端中央で倉庫と工場の間に建つ。木造平屋建、切妻造セメント瓦葺で、外壁は下見板張、小屋はキングポストトラス組とする。内部は床板張の一室で、棚を整然と配し、現在も原糸を収納する。鋸形の屋根の工場と並び、敷地西側の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013409"},{"id":"00013402","register_sub_id":"101","register_pk":"368487","name":"葛利毛織工業株式会社工場","kana":"くずりけおりこうぎょうかぶしきがいしゃこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33546667,"lng":136.75948889,"geo_status":"db","era":"昭和7年頃／昭和20年頃・同30年代増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積563㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0549","desc":"一宮市の中西部、木曽川左岸の玉ノ井地区に位置し、敷地北側に建つ、毛織物の生産工場。木造平屋建、桟瓦葺で、鋸形の屋根形状で四スパンから成り、小屋はトラス組。内部は一室で高窓から採光し、独立柱を避け織機を配す。織物業の隆盛を伝える工場施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013402"},{"id":"00013403","register_sub_id":"101","register_pk":"368488","name":"葛利毛織工業株式会社事務所","kana":"くずりけおりこうぎょうかぶしきがいしゃじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33515,"lng":136.75946111,"geo_status":"db","era":"昭和7年頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0550","desc":"敷地南端中央の門を入って西側に建つ。木造二階建、寄棟造桟瓦葺で、西側の廊下から離れに続く。小屋はキングポストトラス組、外壁は下見板張。一階は一室で、二階は十畳二室を南北に並べ、主座敷に床、棚を備える。和風の座敷を備えた、外観洋風の事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013403"},{"id":"00013410","register_sub_id":"101","register_pk":"368495","name":"葛利毛織工業株式会社倉庫","kana":"くずりけおりこうぎょうかぶしきがいしゃそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33528333,"lng":136.75926667,"geo_status":"db","era":"昭和32年頃","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0557","desc":"原糸倉庫の南側に連続して建つ。木造平屋建、切妻造セメント瓦葺で、外壁は下見板張とする。南北に長い長方形平面の内部は、東西の二室に分ける。内部には棚を並べ、工場の倉庫として使用する。工場や原糸倉庫と共に敷地西側の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013410"},{"id":"00013406","register_sub_id":"101","register_pk":"368491","name":"葛利毛織工業株式会社男子寮","kana":"くずりけおりこうぎょうかぶしきがいしゃだんしりょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33538056,"lng":136.75962222,"geo_status":"db","era":"昭和27年頃／昭和32年頃増築","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、瓦葺、建築面積43㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0553","desc":"工場の南東に建つ。木造二階建、桟瓦葺で、寄棟造で南北棟の主体部北寄りに東西棟の増築部が接続する。外壁は竪板張のペンキ塗仕上で、一階を倉庫と吹放しの通路とし、二階に男子寮の居室を三室配す。住込みで働いていた時代の様相を伝える工場の附属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013406"},{"id":"00013408","register_sub_id":"101","register_pk":"368493","name":"葛利毛織工業株式会社土蔵","kana":"くずりけおりこうぎょうかぶしきがいしゃどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前114他","lat":35.33531667,"lng":136.75936389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0555","desc":"敷地中央西寄りで工場と離れの間に建つ。土蔵造二階建、切妻造桟瓦葺で、北、東面に下屋を廻す。内部は一、二階とも一室で、内壁には竪板を張る。本体部分は家財蔵、下屋は工場の倉庫として使用する。敷地内で最も古く、近代産業施設の景観に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013408"},{"id":"00013405","register_sub_id":"101","register_pk":"368490","name":"葛利毛織工業株式会社離れ","kana":"くずりけおりこうぎょうかぶしきがいしゃはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1他","lat":35.33525278,"lng":136.75939167,"geo_status":"db","era":"昭和7年頃／昭和25年頃・同50年頃増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積97㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0552","desc":"事務所の北西に接続して建つ、経営者家族の住居。木造二階建、入母屋造桟瓦葺で、四周に下屋を廻す。外壁は漆喰塗で、一階は腰壁を、二階は内法高までを竪板張とする。内部は上下階に計八室の座敷を配し、一階主座敷に床と平書院を備える。端正な造りの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013405"},{"id":"00004680","register_sub_id":"101","register_pk":"105670","name":"九重味淋大蔵","kana":"ここのえみりんおおぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県碧南市浜寺町二丁目11","lat":34.874172,"lng":136.98082,"geo_status":"db","era":"宝永3／天明7移築改造","year":1706,"year_source":"db","year_min":1706,"year_max":1706,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積384㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0163","desc":"味淋の基となる酒造のための蔵。土蔵造，２階建，切妻造，桟瓦葺で，東西棟の主体部の南面西端に鈎の手に突出部を設ける。内部は東端部を仕切る以外は１，２階とも広い空間で，外壁は黒塗の押縁下見板で囲う。北面を接道する大型の蔵で味淋工場の象徴的建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004680"},{"id":"00004572","register_sub_id":"101","register_pk":"105562","name":"小島家住宅北酒蔵及び北蔵","kana":"こじまけじゅうたくきたさかぐらおよびきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券633","lat":35.38315132,"lng":136.94022292,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積150㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0176","desc":"敷地北端部に建つ。北酒蔵主体部，北蔵とも，土蔵造２階建，切妻造，桟瓦葺で，東西棟北酒蔵と南北棟北蔵が隣接して建ち，北酒蔵南面西半に下屋（絞り場）を葺下ろし一体化した形式となる。複雑で変化に富んだ外観を呈し，敷地北半の作業空間を象徴する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004572"},{"id":"00004573","register_sub_id":"101","register_pk":"105563","name":"小島家住宅西酒蔵及び仕込場","kana":"こじまけじゅうたくにしさかぐらおよびしこみば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券633","lat":35.38296676,"lng":136.94012933,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造及び木造3階一部平屋建、瓦葺、建築面積307㎡","structure_material":"土蔵造及び木造3階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0177","desc":"主屋の西背後に平屋，切妻造，桟瓦葺の仕込場を配し，その奥に土蔵造３階建，切妻造，桟瓦葺の西酒蔵が接続する。仕込場は全体が吹放しで洗場，釜場をとり，西酒蔵は１階を麹室，熟成場，２階以上を原料，道具置場とする。大規模で醸造業独特の構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004573"},{"id":"00007215","register_sub_id":"101","register_pk":"108197","name":"墨会館","kana":"すみかいかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県一宮市小信中島字南九反11-1","lat":35.312874,"lng":136.745605,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積2089㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2008.07.08(平成20.07.08)","register_no":"23 － 0308","desc":"丹下健三設計のＲＣ造事務所建築。台形敷地北辺の２階建事務室棟と南半の平屋建ホール棟を玄関車寄で接続する。１階外壁は非構造体で、上端にスリットを入れて採光とする。ダブルビームの大梁、打放しコンクリートなど、丹下の初期作品の特徴が見られる佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007215"},{"id":"00011325","register_sub_id":"101","register_pk":"209162","name":"中定商店昭三蔵","kana":"なかさだしょうてんしょうさんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県知多郡武豊町字小迎51","lat":34.855225,"lng":136.922712,"geo_status":"db","era":"昭和3頃／昭和20頃・同63・平成12改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積202㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"23－0470","desc":"敷地南東隅に建つ平屋建、切妻造妻入の土蔵。もとは仕込、圧搾場として建てられたもので、大きな仕込桶を多数並べるために、小屋はキングポストトラスを用いて梁間約一一メートルの大スパンを飛ばす。窓は小庇を付けた高窓として、町の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011325"},{"id":"00011324","register_sub_id":"101","register_pk":"209161","name":"中定商店昭二蔵","kana":"なかさだしょうてんしょうにぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県知多郡武豊町字小迎51","lat":34.855341,"lng":136.92262,"geo_status":"db","era":"昭和2頃／昭和中期・同60改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積87㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"23－0469","desc":"敷地南寄りに建つ平屋建の土蔵。もとは仕込、圧搾場として建てられたもので、キングポストトラスを用いた洋小屋とする。外壁には黒色の簓子下見板を張り、開口には白漆喰で窓枠を打って、コントラストを付ける。醸造業で栄えた武豊の町並み景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011324"},{"id":"00011323","register_sub_id":"101","register_pk":"209160","name":"中定商店大五蔵","kana":"なかさだしょうてんだいごぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県知多郡武豊町字小迎51","lat":34.855483,"lng":136.922424,"geo_status":"db","era":"大正5／昭和41・同48・同62改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積106㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"23－0468","desc":"中定商店は、味噌・溜を専業とする醸造家。大五蔵は変形敷地にあわせた台形平面を持つ。もとは仕込蔵として建てられた。二階建ながら、二階は建ちが低く「二階麹」と呼ばれ、味噌玉に麹菌を繁殖させる部屋とする。黒色の壁面が特色ある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011323"},{"id":"00010164","register_sub_id":"101","register_pk":"197997","name":"西駒屋田村家住宅主屋","kana":"にしこまやたむらけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊橋市二川町字中町147-1","lat":34.724,"lng":137.449851,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積195㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0412","desc":"東海道二川宿に位置する町家で、醸造業を営んでいた。街道に南面して建ち、床上部を二列六室とする。東列はミセ、ナカノマ、ダイドコロ、西列はオクミセ、ブツマ、オクノマとする。床上部正面に出格子をたて、上下階とも軒を出桁造とする。宿場の風情を醸す町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010164"},{"id":"00010165","register_sub_id":"101","register_pk":"197998","name":"西駒屋田村家住宅土蔵","kana":"にしこまやたむらけじゅうたくどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊橋市二川町字中町147-1","lat":34.724187,"lng":137.449901,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0413","desc":"主屋の北方に南北棟で建つ。桁行六間、梁間三間の二階建土蔵。中央の柱で桁行梁を受け、小屋は登梁とする。家財道具を納める蔵で、東に出入口を開く。東正面の上部を漆喰、腰下を黒漆喰で塗り分け、側背面三方を簓子下見板張とする。屋敷構えを構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010165"},{"id":"00000051","register_sub_id":"101","register_pk":"101041","name":"八丁味噌本社蔵（史料館）","kana":"はっちょうみそほんしゃくら（しりょうかん）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県岡崎市八帖町字往還通69","lat":34.9578185,"lng":137.15256494,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積463㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"23 － 0002","desc":"「カクキュウ」の商号で知られる大規模な総２階の土蔵建築で，昭和16年まで味噌仕込み用の蔵として使用されていた。石垣の基壇上に黒塗りの下見板貼りとし，２層目は白漆喰塗りである。壁面に開けられた格子窓が連続するさまが特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000051"},{"id":"00000050","register_sub_id":"101","register_pk":"101040","name":"八丁味噌本社事務所","kana":"はっちょうみそほんしゃじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県岡崎市八帖町字往還通69","lat":34.95786976,"lng":137.1530007,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、トタン葺、建築面積339㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"23 － 0001","desc":"「カクキュウ」の商号で知られる八丁味噌製造業者の本社社屋。南北の２つの棟が中庭と土間をはさんで接続している。教会堂風の構成と，白い柱型と壁面の下見板の濃茶色とを対照させた意匠が特徴的である。内部は洋風の意匠でまとめられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000050"},{"id":"00006586","register_sub_id":"101","register_pk":"107569","name":"萬乗醸造内井戸","kana":"ばんじょうじょうぞううちいど","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.064716,"lng":136.933243,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、面積4.9㎡2基よりなる","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0243","desc":"元蔵の南面近くに位置し，南北方向に２本が並んで掘られている。石造の円形井戸枠の外径はともに２．５ｍ，深さは約８ｍ。創業期以来の井戸であり，元蔵井戸とも称される。良質な水を必要とする醸造業に不可欠な設備である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006586"},{"id":"00006587","register_sub_id":"101","register_pk":"107570","name":"萬乗醸造旧仕込蔵及び樽修理場","kana":"ばんじょうじょうぞうきゅうしこみぐらおよびたるしゅうりば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田3-2他","lat":35.06484509,"lng":136.93395579,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0244","desc":"土蔵の東面沿い道路を挟んだ向かいの敷地に南北棟で建つ。桁行８間，梁間３間規模，切妻造，桟瓦葺の２階建土蔵で，道路側西面全面に１間半幅の下屋を差し掛ける。戸口は南面西寄りと西面北寄りに開く。新町通りの突き当たりに位置し，アイストップになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006587"},{"id":"00006582","register_sub_id":"101","register_pk":"107565","name":"萬乗醸造旧精米作業場","kana":"ばんじょうじょうぞうきゅうせいまいさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.06485,"lng":136.93367,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積125㎡、門及び煙突付","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0235","desc":"土蔵の南方に南北棟で建つ。桁行６間半，梁間３間半，切妻造，桟瓦葺の木造平屋建で，南側を旧精米所とし，北側を中庭への通路とする。西面北半に下屋を，南半に切妻屋根を掛けて共に倉庫とする。東面には萬乗醸造のシンボルである煉瓦造煙突を添わす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006582"},{"id":"00006579","register_sub_id":"101","register_pk":"107562","name":"萬乗醸造新蔵","kana":"ばんじょうじょうぞうしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.065182,"lng":136.933517,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積298㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0239","desc":"主屋の西方，中蔵の北面に接して南北棟で建つ。桁行１５間，梁間６間，切妻造，桟瓦葺，２階建の長大な仕込蔵で，内部に２列８本の通し柱を立てる。外部は縦板張，２階は生子鉄板張とする。北妻面を新町通りに見せ，主屋・土蔵とともに重厚な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006579"},{"id":"00006588","register_sub_id":"101","register_pk":"107571","name":"萬乗醸造外井戸","kana":"ばんじょうじょうぞうそといど","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区大高町字土廻間8他","lat":35.06437796,"lng":136.93360423,"geo_status":"db","era":"明治初期／昭和初期増設","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"陶製及びコンクリート造、面積4.9㎡1基及び面積1.8㎡5基よりなる","structure_material":"陶製及びコンクリート造","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0245","desc":"醸造場敷地の南方，土蔵東面道路に面する飛地に所在する。６本が掘られ，うち北側の５本は径１．５ｍ，深さ５ｍ，南方の１本は径２．５ｍ，深さ８ｍであり，井戸枠は４基がコンクリート製，２基が常滑焼製になる。醸造場の拡張，発展を物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006588"},{"id":"00006578","register_sub_id":"101","register_pk":"107561","name":"萬乗醸造中蔵","kana":"ばんじょうじょうぞうなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.064972,"lng":136.933243,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積343㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0238","desc":"敷地の南西部，元蔵の西に南北棟で建つ。桁行１４間，梁間４間，切妻造，桟瓦葺，２階建の長大な仕込蔵。中央棟通りに３本の通し柱を立てる。西面には２間半幅の下屋を差し掛けて１階の平面規模を梁行６間半とする。創業期の仕込蔵で，蔵３棟のうち最も古い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006578"},{"id":"00006580","register_sub_id":"101","register_pk":"107563","name":"萬乗醸造白米倉庫","kana":"ばんじょうじょうぞうはくまいそうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.065048,"lng":136.933502,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積46㎡、検査室付","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0240","desc":"離れの南方，新蔵の東に位置し，東西棟で建つ。桁行４間，梁間２間半，切妻造，桟瓦葺の２階建土蔵で，南面に戸口を開け，東妻面には奥行１間半，梁間２間半，入母屋造，桟瓦葺の検査室が取り付く。旧精米作業場，元蔵米蒸し室とともに主屋南方の中庭を囲う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006580"},{"id":"00006581","register_sub_id":"101","register_pk":"107564","name":"萬乗醸造瓶詰作業場","kana":"ばんじょうじょうぞうびんづめさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.064697,"lng":136.933487,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、鉄板葺、建築面積147㎡、物置付","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0236","desc":"旧精米作業場の南方に東西棟で建つ。桁行９間，梁間４間規模，切妻造，鉄板葺の木造平屋建で，北面東端から敷地境界沿いに北へ桁行６間，梁間１間の物置を延ばし，物置前に広い作業場をとる。真壁造で，小屋組は旧精米作業場と同様キングポストトラスとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006581"},{"id":"00006577","register_sub_id":"101","register_pk":"107560","name":"萬乗醸造元蔵","kana":"ばんじょうじょうぞうもとぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.064804,"lng":136.933319,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積338㎡、米蒸し室及び試験室付","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0237","desc":"主屋の南方に位置し，瓶詰作業場の西に接して建つ。桁行９間，梁間８間，切妻造，桟瓦葺，２階建の仕込蔵で，北面東寄りに桁行６間半，梁間４間，南北棟の米蒸し室が取り付き，米蒸し室の西に試験室を配する。外部は簓子下見板張。醸造場の中心をなす施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006577"},{"id":"00004241","register_sub_id":"101","register_pk":"105231","name":"半田赤レンガ建物（旧カブトビール工場）創建時主棟","kana":"はんだあかれんがたてもの（きゅうかぶとびーるこうじょう）そうけんじしゅとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県半田市榎下町8","lat":34.90141497,"lng":136.92849585,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"煉瓦造2階建一部5階建、鉄板葺、建築面積636㎡","structure_material":"煉瓦造2階建一部5階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0134","desc":"煉瓦造２階建の発酵室・貯蔵室に同５階建の事務室・技師室が接続する。屋根は切妻造鉄板葺。窓は櫛形アーチに要石，５階窓は半円アーチに迫元石・要石付で飾る。発酵室・貯蔵室の２階床と天井はＩ形鉄梁に煉瓦アーチを充填した耐火床とする。設計は妻木頼黄。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004241"},{"id":"00004243","register_sub_id":"101","register_pk":"105233","name":"半田赤レンガ建物（旧カブトビール工場）貯蔵庫棟","kana":"はんだあかれんがたてもの（きゅうかぶとびーるこうじょう）ちょぞうことう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県半田市榎下町8","lat":34.90159351,"lng":136.92845179,"geo_status":"db","era":"明治41／大正7・大正10増築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積1359㎡","structure_material":"煉瓦造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0136","desc":"主棟の北辺から西辺に接続する増築部で，発酵室・貯蔵室に用いられた。煉瓦造２階建，切妻造，鉄板葺の南北棟３棟が，主棟北から反時計回りに順次増築された。壁体はイギリス積。妻壁上部はペディメントに造り，円窓を飾る。窓は要石付の櫛形アーチとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004243"},{"id":"00004242","register_sub_id":"101","register_pk":"105232","name":"半田赤レンガ建物（旧カブトビール工場）ハーフティンバー棟","kana":"はんだあかれんがたてもの（きゅうかぶとびーるこうじょう）はーふてぃんばーとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県半田市榎下町8","lat":34.90183658,"lng":136.92834089,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積784㎡","structure_material":"木骨煉瓦造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0135","desc":"主棟南に接続する木骨煉瓦造の平屋建で，東辺部は胴差を入れて高窓を開いて切妻屋根とし，南側は主棟から片流の屋根で，鉄板葺とする。瓶洗・瓶詰・荷造等の出荷作業を行った。戸口は両開板扉とし，当初の窓は上下げ窓であったが閉鎖した。設計は妻木頼黄。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004242"},{"id":"00003884","register_sub_id":"101","register_pk":"104874","name":"明治村菊の世酒蔵","kana":"めいじむらきくのよさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34548286,"lng":136.98896159,"geo_status":"db","era":"明治28／昭和58移築","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積654㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0118","desc":"桁行１８間，梁行９間の土蔵造２階建。切妻造，桟瓦葺で片側に庇がつく。外壁は押縁下見板で保護し，小庇付の窓を多数開く。小屋組は梁行を３等分して柱を立てて鳥居形に組み，両側から登り梁を渡して和小屋とする。移築時，北半にＲＣ造展示室を組み込んだ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003884"},{"id":"00003663","register_sub_id":"101","register_pk":"104653","name":"明治村京都中井酒造","kana":"めいじむらきょうとなかいしゅぞう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34165366,"lng":136.98996542,"geo_status":"db","era":"明治3／平成5移築","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造2階建、瓦葺、建築面積155㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0076","desc":"切妻造，平入の木造つし２階建町家。屋根は起りのある桟瓦葺で，右手を落棟とする。正面１階は太い格子と無双窓，２階は虫籠窓である。内部は通り土間の左が居室，右に穀物置場，井戸と洗米所，煉瓦造蒸し竈などがあり，当時の酒造業の様子を示す遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003663"},{"id":"00003866","register_sub_id":"101","register_pk":"104856","name":"明治村工部省品川硝子製造所","kana":"めいじむらこうぶしょうしながわがらすせいぞうしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34435065,"lng":136.99032426,"geo_status":"db","era":"明治10頃／昭和44移築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積123㎡","structure_material":"煉瓦造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0100","desc":"煉瓦造，一部中２階付き。木造キングポストトラス小屋組による切妻屋根に，換気用の越屋根を載せる。外壁はイギリス積で軒蛇腹が巡る。開口部は半円アーチのファンライト付と，まぐさ石形式の２種を用い，石材がアクセントとなる。明治初期官営工場の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003866"},{"id":"00003659","register_sub_id":"101","register_pk":"104649","name":"明治村鉄道局新橋工場","kana":"めいじむらてつどうきょくしんばしこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34036954,"lng":136.98932477,"geo_status":"db","era":"明治22／昭和41移築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"鉄造平屋建、銅板葺、建築面積463㎡","structure_material":"鉄造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0072","desc":"鉄造平屋建，越屋根付き切妻屋根を銅板葺とする。妻には半円のファンライトを飾り，半円アーチの扉口に両開き戸を吊り込む。鋳鉄柱，キングポストトラスの小屋組材，鉄製下見板，サッシ類の鉄材は全て国産で，当時の工業技術を示す貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003659"},{"id":"00008295","register_sub_id":"101","register_pk":"133937","name":"アミカン本社事務所","kana":"あみかんほんしゃじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市富田浜元町1867","lat":35.00120405,"lng":136.6536299,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木骨コンクリート造2階建、塔屋付、建築面積100㎡","structure_material":"木骨コンクリート造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0092","desc":"旧東海道に面する敷地に建ち、建築面積１００㎡、木骨コンクリート造２階建塔屋付である。南西隅を四分一円弧とし、外壁はスクラッチタイル貼とモルタル洗出しとし、縦長窓を連続的に配置する。大小の矩形を取り混ぜた変化のある立面意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008295"},{"id":"00008296","register_sub_id":"101","register_pk":"133938","name":"アミカン本社正門","kana":"あみかんほんしゃせいもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市富田浜元町1867","lat":35.00117137,"lng":136.65348428,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"コンクリート造、間口2.7m","structure_material":"コンクリート造","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0093","desc":"敷地西辺の中央南寄りに、やや後退して建ち、南北に煉瓦塀を延ばす。間口を５．８ｍとし、門柱は、高さ３．１ｍのコンクリート造、洗出し仕上げで頂部をドーム状につくり、ボーダーをまわす。かつては左右に脇門を開いていたが、南側は煉瓦で閉ざされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008296"},{"id":"00008297","register_sub_id":"101","register_pk":"133939","name":"アミカン本社煉瓦塀","kana":"あみかんほんしゃれんがべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市富田浜元町1867","lat":35.00130487,"lng":136.65355721,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、総延長46m","structure_material":"煉瓦造","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0094","desc":"敷地西面に建ち、本館正面に構えた正門の両側に折れ曲がりに延びる。煉瓦造で、総延長４６ｍを測る。２．２ｍ毎に柱型を現し、各間を長手積煉瓦で充たし、頂部は柱と同幅の臥梁形に積んだ煉瓦で繋ぐ。重厚な外観で、近代産業による発展の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008297"},{"id":"00009491","register_sub_id":"101","register_pk":"194284","name":"石川酒造井戸屋形","kana":"いしかわしゅぞういどやかた","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99427696,"lng":136.53973462,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、面積6.8㎡、井戸付","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0143","desc":"敷地中央の中庭から南西寄り、主屋北側に建つ。木造、切妻造桟瓦葺、内ころびの４本柱の上部を頭貫と方杖とにより固める。四方吹放しで、中央部に石積で井桁が組まれた井戸がある。伏流水が多く自噴する造酒屋における敷地内の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009491"},{"id":"00009486","register_sub_id":"101","register_pk":"194279","name":"石川酒造大蔵","kana":"いしかわしゅぞうおおぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99474239,"lng":136.53974462,"geo_status":"db","era":"大正5年／昭和21年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積566㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0138","desc":"敷地北端に建つ。土蔵造二階建、切妻造桟瓦葺、桁行三二・八メートル梁間一四・六メートル。高さ一〇メートルを超える大規模な酒造施設で、黒い下見板を軒下まで張った外観は地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009486"},{"id":"00009487","register_sub_id":"101","register_pk":"194280","name":"石川酒造釜場","kana":"いしかわしゅぞうかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.9945537,"lng":136.53975758,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積166㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0139","desc":"北側に大蔵、西側に槽場に接して建つ。木造平屋建、切妻造桟瓦葺、桁行一八・二メートル梁間九・一メートル。南東部に中二階を設ける。小屋組は和小屋、天井を表しとする。大棟に越屋根を設け、換気を促す。洗米、蒸しなど酒造の行程を担う大型の酒造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009487"},{"id":"00009482","register_sub_id":"101","register_pk":"194275","name":"石川酒造北文庫蔵","kana":"いしかわしゅぞうきたぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99433609,"lng":136.53956021,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0134","desc":"南文庫蔵の北東側に建つ。土蔵造二階建、切妻造桟瓦葺、桁行五・四メートル梁間四・七メートル、東面に出入口を開け、下屋を設ける。外壁は白漆喰仕上で鉢巻きを廻し、腰は東面を洗い出し仕上げ、他三方は下見板を張る。南文庫蔵と並び当家の繁栄ぶりを表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009482"},{"id":"00009484","register_sub_id":"101","register_pk":"194277","name":"石川酒造旧米庫","kana":"いしかわしゅぞうきゅうこめこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99428672,"lng":136.54001825,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積49㎡","structure_material":"土蔵造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0136","desc":"旧精米場の北側に建つ。木造平屋建、切妻造桟瓦葺、桁行七・三メートル梁間五・五メートル。西面に下屋を付け、人造石研ぎ出しと黒漆喰で縁取られた出入口を開ける。小屋組は和小屋、天井は表しとし内部空間を広く取る。老舗造酒屋を構成する建築群のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009484"},{"id":"00009483","register_sub_id":"101","register_pk":"194276","name":"石川酒造旧精米場","kana":"いしかわしゅぞうきゅうせいまいじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99419392,"lng":136.54003015,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積98㎡、門付","structure_material":"土蔵造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0135","desc":"敷地南東隅に建つ。切妻造桟瓦葺、桁行一〇・九メートル梁間五・五メートル。人造石研ぎ出しと黒漆喰で縁取られた出入口を西面に二箇所開け下屋が付く。外壁は白漆喰塗、腰高に下見板を張る。正門を介して主屋と並び、大規模な地酒屋の南面の構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009483"},{"id":"00009492","register_sub_id":"101","register_pk":"194285","name":"石川酒造自噴井戸","kana":"いしかわしゅぞうじふんいど","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99451919,"lng":136.53988548,"geo_status":"db","era":"大正5年／昭和29年増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造及びコンクリート造、面積7.5㎡","structure_material":"煉瓦造及びコンクリート造","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0144","desc":"敷地中央の中庭に位置する。煉瓦造の貯水槽を基とし、北側にコンクリート造の貯水槽二基及びポンプを増設する。筒状を呈した高位の貯水槽を取り囲むように低位の貯水槽が逆コの字形に配される。潤沢に伏流水が湧くことを物語る、造酒屋にふさわしい工作物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009492"},{"id":"00009479","register_sub_id":"101","register_pk":"194272","name":"石川酒造主屋","kana":"いしかわしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99416061,"lng":136.53981005,"geo_status":"db","era":"明治24年／昭和元年増築・昭和23年・平成元年改修","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積296㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0131","desc":"敷地南側に建つ。木造平屋建、入母屋造桟瓦葺。建築面積二九六平方メートル。南側に大戸口を開け、通り土間を設ける。その西側に六室を配し、三方に広く縁を廻す。外壁は黒漆喰塗で腰は下見板張とする。明治期の造酒屋を構成する重厚な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009479"},{"id":"00009490","register_sub_id":"101","register_pk":"194283","name":"石川酒造貯蔵庫及び事務所","kana":"いしかわしゅぞうちょぞうこおよびじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.9944283,"lng":136.53973153,"geo_status":"db","era":"明治後期／昭和23年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積155㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0142","desc":"敷地のほぼ中央に建つ。土蔵造一部木造二階建、切妻造桟瓦葺、建築面積一五五平方メートル。東側に下屋を設け、二箇所出入口を開ける。外壁は白漆喰塗、腰は竪板張だが、事務所前のみ竪窓を嵌め込み漆喰で意匠的に縁取りし、特徴的な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009490"},{"id":"00009485","register_sub_id":"101","register_pk":"194278","name":"石川酒造納屋","kana":"いしかわしゅぞうなや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.9944283,"lng":136.54002301,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0137","desc":"敷地東側、旧米庫の北側に建つ。木造二階建、切妻造桟瓦葺、桁行一三・六メートル梁間四・五メートル。西側に小部屋が張り出し、北側に下屋を付設する。旧精米場、旧米庫と並び、通りから腰高に下見板を張る外壁を連続させ、重厚な造酒屋の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009485"},{"id":"00009493","register_sub_id":"101","register_pk":"194286","name":"石川酒造西土塀","kana":"いしかわしゅぞうにしどべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99413807,"lng":136.5395022,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長19m","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0145","desc":"敷地南西角から延び、南文庫蔵につながる。木造、高さ三・一メートル、桟瓦を葺く。外壁は腰高に下見板を張り、小壁を白漆喰仕上げの真壁とし、腕木が出桁を支持する。内側は杉板張とする。広大な老舗の造酒屋を構成する要素として、景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009493"},{"id":"00009480","register_sub_id":"101","register_pk":"194273","name":"石川酒造西の座敷","kana":"いしかわしゅぞうにしのざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99415466,"lng":136.539584,"geo_status":"db","era":"明治31年／平成22年改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0132","desc":"敷地南端、主屋の西側に建ち、渡り廊下で繋がる。木造平屋建、片入母屋造桟瓦葺、建築面積七二平方メートル。田の字型に四室を配し、いずれも竿縁天井とする。トコのある主室と次の間を南側に設け、濡れ縁を介して前庭を望む。接客用の良質な和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009480"},{"id":"00009489","register_sub_id":"101","register_pk":"194282","name":"石川酒造壜詰場","kana":"いしかわしゅぞうびんづめば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99446518,"lng":136.5395959,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積280㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0141","desc":"敷地西端、槽場の南側に建つ。木造二階建、切妻造桟瓦葺、桁行二一・八メートル梁間一○・九メートル。東側北寄りに下屋が付くが釜場に覆われる。外壁の下部は竪板張、上部は下見板張とし、上下二つの窓を等間隔に穿つ。老舗造酒屋にふさわしい景観を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009489"},{"id":"00009488","register_sub_id":"101","register_pk":"194281","name":"石川酒造槽場","kana":"いしかわしゅぞうふなば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99461794,"lng":136.53962398,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積141㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0140","desc":"敷地の西端に建つ。木造二階建、切妻造桟瓦葺、建築面積一四一平方メートル。東側に下屋が付くが釜場に覆われる。北西隅を掘り込み、モザイクタイル貼の槽場とし、搾りの行程が行われた。外壁は下見板張で覆われ、重厚な酒造施設の一群を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009488"},{"id":"00009481","register_sub_id":"101","register_pk":"194274","name":"石川酒造南文庫蔵","kana":"いしかわしゅぞうみなみぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99425876,"lng":136.53952749,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0133","desc":"敷地西側、西の座敷の北側に建つ。土蔵造二階建、切妻造桟瓦葺、桁行七・二メートル梁間五・八メートル。東面に出入口を二箇所開け、下屋を設ける。基礎は切石積とし、外壁は白漆喰仕上で鉢巻きを廻し、腰は東面を洗い出し仕上げ、他三方は下見板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009481"},{"id":"00002547","register_sub_id":"101","register_pk":"103537","name":"伊勢河崎商人館応接室及び前室","kana":"いせかわさきしょうにんかんおうせつしつおよびぜんしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.496506,"lng":136.71756,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積9.0㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"24 － 0038","desc":"旧小川酒店主屋西側の門を入って左手に位置する。応接室は桁行２間，梁間１間半規模，南北棟，切妻造，桟瓦葺の１室洋館で，室内西面に暖炉を備える。前室は主屋土間に連絡する渡廊下の西半部にあたり，門・洋館とともに酒店の洋風接客空間を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002547"},{"id":"00002268","register_sub_id":"101","register_pk":"103258","name":"伊勢河崎商人館サイダー検査室","kana":"いせかわさきしょうにんかんさいだーけんさしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.49674172,"lng":136.71748926,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造平屋建、建築面積12㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0037","desc":"小川酒店では昭和期に入り，酒卸業に加え，サイダー工場を併設して生産販売していた。サイダー検査室は，鉄筋コンクリート造，平屋建，陸屋根でパラペットに瓦を載せ，外壁下部は洗い出し仕上げとする。小規模だが，近代における製造業の証左となる建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002268"},{"id":"00002548","register_sub_id":"101","register_pk":"103538","name":"伊勢河崎商人館サイダーろ過施設","kana":"いせかわさきしょうにんかんさいだーろかしせつ","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.496574,"lng":136.717529,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、鋼板葺、建築面積3.0㎡","structure_material":"鉄筋コンクリート造","registered":"2001.11.20(平成13.11.20)","register_no":"24 － 0039","desc":"旧小川酒店の西裏門近くに建つ。正面間口２．５ｍ，奥行１．２ｍ規模，高さ６ｍほどの鉄筋コンクリート造構造物で，下部は正面に２連の欠円アーチによる開口をとり，上部を水槽状に造る。サイダー検査室とともにサイダー製造を偲ばせる数少ない施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002548"},{"id":"00014394","register_sub_id":"101","register_pk":"511383","name":"於茂千也函（伊藤家住宅土蔵）","kana":"おもちゃばこ（いとうけじゅうたくどぞう)","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県四日市市富田一丁目983-1","lat":35.00420556,"lng":136.65203889,"geo_status":"db","era":"江戸末期／明治前期・昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積120㎡","structure_material":"土蔵造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"24 - 0321","desc":"旧富田町に所在し、個人が収集した郷土玩具を収納・展示する蔵。土蔵造平屋建、切妻造桟瓦葺で南に葺降ろして戸前とする。壁は漆喰塗で腰は海鼠壁。東半を土間、西半を床上２室とし、数寄屋風天井の次の間、書院付の奥座敷とする。趣味人の数寄屋風座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014394"},{"id":"00015465","register_sub_id":"101","register_pk":"533480","name":"神楽酒造酒蔵兼釜場","kana":"かぐらしゅぞうさかぐらけんかまば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県四日市市室山町326","lat":34.95519444,"lng":136.57867778,"geo_status":"db","era":"安政5年(1858)／大正後期増築、平成19年改修","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"土蔵造2階一部平屋建、瓦葺、建築面積557㎡、煙突付","structure_material":"土蔵造2階一部平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"24 - 0334","desc":"市街地西部に位置する酒造業の酒蔵兼釜場。２階建切妻造桟瓦葺東西棟で、北・南面に下屋を付し、南面西寄りに切妻造南北棟の釜場を突出し、煉瓦造煙突を取込む。一階は土間で蒸米場など、二階は板敷で物置などとする。地域の酒造業の歴史を伝える貴重な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015465"},{"id":"00015466","register_sub_id":"101","register_pk":"533481","name":"神楽酒造西酒蔵","kana":"かぐらしゅぞうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市室山町326","lat":34.95524722,"lng":136.57841111,"geo_status":"db","era":"明治中期／平成19年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積406㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"24 - 0335","desc":"酒蔵兼釜場の西に位置する仕込蔵。二階建切妻造桟瓦葺東西棟の長大な土蔵を南北に並べ、棟境には壁を設けず、内部を一体として利用する。一階は土間の仕込場、二階は板敷の倉庫などとし、棟境上部に軒樋を現す。２棟を連結させた特徴的な外観の大規模な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015466"},{"id":"00014395","register_sub_id":"101","register_pk":"511384","name":"かつおの天ぱく主屋","kana":"かつおのてんぱくおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県志摩市大王町波切字石干谷393","lat":34.27724444,"lng":136.89475833,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"24 - 0322","desc":"太平洋を望む大王崎に建つ鰹節製造業の住宅である。東の崖と南の道路から一段低く敷地を構え、木造平屋建の切妻造桟瓦葺、竪板張の外壁で風に耐える。現在は一階南西の四畳間で商品陳列し、他は物置とする。波切漁港の水揚げを直ちに加工できる好立地にある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014395"},{"id":"00014396","register_sub_id":"101","register_pk":"511385","name":"かつおの天ぱく作業場","kana":"かつおのてんぱくさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県志摩市大王町波切字石干谷393","lat":34.27717778,"lng":136.89471389,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階一部平屋建、瓦葺及び鉄板葺、建築面積148㎡","structure_material":"木造2階一部平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"24 - 0323","desc":"二階建の燻し小屋と黴付小屋で、北の主屋との間の大屋根が作業場を覆う。湾曲した海側外壁は腰モルタル塗、上部竪板張で、桟瓦葺の切妻屋根が独特の外観を呈す。焙乾窯は火床を地下に設け、セイロを並べて積む。閉鎖的な黴付小屋に棲む菌が鰹節の味を決める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014396"},{"id":"00009494","register_sub_id":"101","register_pk":"194287","name":"木屋正酒造店舗兼主屋","kana":"きやしょうしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市本町314-1","lat":34.61933412,"lng":136.08808113,"geo_status":"db","era":"明治22年／大正2年増築・昭和63年改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積250㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0146","desc":"初瀬街道に面して建つ。間口一五・八メートルの木造つし二階建、切妻造桟瓦葺で、正面に下屋を設ける。正面左手を出入口及びミセノマとし、右手の床上部前面の張出しは腰を簓子下見板張とする。上部は漆喰塗で虫籠窓を穿ち、老舗造酒屋らしい佇まいを呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009494"},{"id":"00016675","register_sub_id":"101","register_pk":"579159","name":"旧伊賀焼陶磁器工業協同組合事務所","kana":"きゅういがやきとうじきこうぎょうきょうどうくみあいじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊賀市丸柱字長谷474-5他","lat":34.839978,"lng":136.129265,"geo_status":"db","era":"昭和14年／令和3年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"24 - 0345","desc":"市街地北方の山間に所在する伊賀焼の旧協同組合事務所。平屋建寄棟造桟瓦葺、北面切妻造玄関ポーチ付き。外壁下見板張、北・南面にガラス窓を連続して建てる。内部は和風で、南東隅の部屋は床を構え長押を廻す。窯元が多く所在する地域を象徴する旧事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016675"},{"id":"00001712","register_sub_id":"101","register_pk":"102702","name":"旧東洋紡績株式会社富田工場原綿倉庫","kana":"きゅうとうようぼうせきかぶしきがいしゃとみだこうじょうげんめんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県四日市市富州原町221-2","lat":35.00677659,"lng":136.65688221,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積1072㎡","structure_material":"煉瓦造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"24 － 0024","desc":"東洋紡績施設のなかで最大規模を有した工場の原綿倉庫で、敷地東南辺に沿って５つの妻面を並べる。桁行約１８メートル梁間約９メートル規模、切妻造の庫室５棟が一体となった形態をもち、煉瓦造壁体四周の要所にはバットレスをあらわす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001712"},{"id":"00013561","register_sub_id":"101","register_pk":"504928","name":"糀屋太郎兵衛商店奥蔵及び米蔵","kana":"こうじやたろべえしょうてんおくぐらおよびこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市魚町1773","lat":34.57528056,"lng":136.53120833,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"24 － 0284","desc":"道具蔵北側に南面して建ち、西側の糀原料の米を収めた米蔵と、東側の糀製造の道具類を収めた奥蔵から成る。本瓦葺の土蔵造二階建で、平入の正面下屋を蔵前とする。外壁は漆喰で軒先まで塗込めて鉢巻を廻し、敷地外側面は下見板張とする。糀製造を支えた施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013561"},{"id":"00013562","register_sub_id":"101","register_pk":"504929","name":"糀屋太郎兵衛商店糀室","kana":"こうじやたろべえしょうてんこうじむろ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市魚町1773","lat":34.57525833,"lng":136.53114444,"geo_status":"db","era":"明治26年頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、屋根漆喰塗込、建築面積16㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"24 － 0285","desc":"奥蔵及び米蔵の西側に南面して建つ糀室。緩勾配屋根の土蔵造で、屋根を含めて全体を漆喰で塗込め、正面右上方に黒漆喰塗の眉を描く。内部は半地下で、登梁形式の小屋とし、床、壁はモルタル塗で、南東に糀製造用の筵を置く立上りを設ける。糀製造の中核施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013562"},{"id":"00013559","register_sub_id":"101","register_pk":"504926","name":"糀屋太郎兵衛商店店舗兼主屋","kana":"こうじやたろべえしょうてんてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市魚町1773","lat":34.57520556,"lng":136.53102222,"geo_status":"db","era":"明治26年頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"24 － 0282","desc":"旧松坂城下東方にある代々糀製造販売を営む商家。道路に西面して建つ二階建切妻造で、正面に下屋、両端に袖壁を付す。外壁は黒漆喰塗で、一階に出格子、二階に出窓と虫籠窓を並べる。内部は南に土間、北に一列四室を配す。大火後の旧城下の町家の有様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013559"},{"id":"00013560","register_sub_id":"101","register_pk":"504927","name":"糀屋太郎兵衛商店道具蔵","kana":"こうじやたろべえしょうてんどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県松阪市魚町1773他","lat":34.57521667,"lng":136.531225,"geo_status":"db","era":"安政2年(1855)／明治26年頃増築","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"24 － 0283","desc":"敷地南東に西面して建つ家財蔵。本瓦葺の土蔵造二階建で、妻入の正面下屋を蔵前とする。外壁は漆喰で軒先まで塗込めて鉢巻を廻し、敷地外側面は下見板張とする。内部は板敷で壁を竪板張とし、登梁形式の小屋とする。大火を逃れた近世の屋敷構えを伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013560"},{"id":"00010468","register_sub_id":"101","register_pk":"199424","name":"長谷園奥の蔵","kana":"ながたにえんおくのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱569","lat":34.837587,"lng":136.129553,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0194","desc":"離れの西に接して東西棟で建ち、桁行四・九メートル梁間三・九メートル、土蔵造二階建、切妻造桟瓦葺で、南面に物置を附属する。外壁漆喰塗で鉢巻を廻らし、南東面は腰を海鼠壁、背面は竪板張とする。離れや蔵とともに屋敷北面の歴史的景観の形成に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010468"},{"id":"00010467","register_sub_id":"101","register_pk":"199423","name":"長谷園蔵","kana":"ながたにえんくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱569","lat":34.837564,"lng":136.129739,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0193","desc":"主屋背面に南面し、桁行四・九メートル梁間三メートル、土蔵造二階建、切妻造桟瓦葺で、正面の下屋で離れと接続する。腰高に竪板を張り、鉢巻を廻らす。小屋はアーチ状の梁で棟束と母屋を受ける。かつて帳簿蔵として使われた蔵で、主屋裏庭の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010467"},{"id":"00010472","register_sub_id":"101","register_pk":"199428","name":"長谷園工房一","kana":"ながたにえんこうぼういち","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱568-4","lat":34.83728,"lng":136.129669,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0198","desc":"敷地内通路沿いに東西棟で建つ平屋建の工房で、切妻造桟瓦葺である。外壁に竪板を張り、妻壁を漆喰塗とする。内部は一室で南面各間を窓として採光を図り、棹縁天井を張る。かつて轆轤に動力を伝えた機械の一部も残されており、陶器の製作工程を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010472"},{"id":"00010473","register_sub_id":"101","register_pk":"199429","name":"長谷園工房二","kana":"ながたにえんこうぼうに","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱568-4","lat":34.837073,"lng":136.129598,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積233㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0199","desc":"工房部の奥寄りに建つ木造平屋建で、Ｌ字形平面の工房である。工房一と同様に外壁竪板張とし、南面に窓を並べて採光を図る。内部は五室に区画して作業場や物置とする。小屋はキングポストトラスを採用して方杖や火打梁で固め、広い梁間を支持する大型の工房。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010473"},{"id":"00010464","register_sub_id":"101","register_pk":"199421","name":"長谷園主屋","kana":"ながたにえんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱569","lat":34.837468,"lng":136.129779,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、茅葺、建築面積185㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0190","desc":"住宅部の敷地東寄りに南面して建つ寄棟造茅葺で、棟と下屋に桟瓦を葺く。東寄りが土間で、床上部は前後に三室ずつ並べて縁を廻らし、南西隅の主座敷は庭に面した十畳で、大振りな床と床脇を備え、組子欄間を飾る。老舗窯元の、風格を備えた上質な住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010464"},{"id":"00010474","register_sub_id":"101","register_pk":"199430","name":"長谷園体験工房","kana":"ながたにえんたいけんこうぼう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱585","lat":34.837015,"lng":136.130085,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0200","desc":"通りの東側に南北棟で建つ、桁行二五メートルを測る長い建物で、傍らに築いた登り窯のための薪置場や釉薬の試験等に使われた。木造平屋建、南面切妻造北面寄棟造、桟瓦葺で、外壁竪板張とし、内壁の一部に荷摺木を残す。往時の製陶情景を偲ばせる施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010474"},{"id":"00009028","register_sub_id":"101","register_pk":"162388","name":"長谷園大正館","kana":"ながたにえんたいしょうかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱字長谷569","lat":34.83741469,"lng":136.13030464,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0118","desc":"山裾の敷地西寄りに位置し、高く積み上げた石垣に建つ木造平屋建。南北棟の半切妻造桟瓦葺、桁行８．９ｍ梁間７．９ｍ。下見板張で上部漆喰仕上げとし、大きく窓を開く開放的な事務所。南正面入口上部に印象的な意匠のアーチ型庇を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009028"},{"id":"00010469","register_sub_id":"101","register_pk":"199425","name":"長谷園展示室一","kana":"ながたにえんてんじしついち","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱569","lat":34.837409,"lng":136.129927,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積156㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0195","desc":"通り沿いで、主屋の東隣に棟を直交させて建つ。木造二階建、切妻造桟瓦葺で、南妻を出入口として下屋を設ける。一階外部を竪板張とし、二階は漆喰仕上げで南妻に窓を開ける。当初は味噌蔵などに使われた、施設内最大の展示室で、風情のある街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010469"},{"id":"00010471","register_sub_id":"101","register_pk":"199427","name":"長谷園展示室三","kana":"ながたにえんてんじしつさん","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱568-4","lat":34.83714,"lng":136.12988,"geo_status":"db","era":"明治期／平成15改修","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0197","desc":"展示室二の南側に平行して建つ展示室。木造二階建、切妻造桟瓦葺で、周囲に下屋を設ける。外壁は真壁漆喰塗で柱や梁の軸組を意匠的に現し、各面に窓を配する。内部は上下階とも一室である。もと米蔵などに使った建物で、建ちが高く、街路景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010471"},{"id":"00010470","register_sub_id":"101","register_pk":"199426","name":"長谷園展示室二","kana":"ながたにえんてんじしつに","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱568-4","lat":34.837218,"lng":136.129891,"geo_status":"db","era":"明治期／昭和49・平成15改修","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0196","desc":"展示室一の南側に向き合い、東西棟で建つ展示室。木造平屋建、東面切妻造西面入母屋造、桟瓦葺で、外壁に竪板を張る。内部は土間の一室で、小屋は和小屋を組む。当初は馬小屋に使われたとされ、一部に床板張であった痕跡も残す。往時の操業様態の一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010470"},{"id":"00009029","register_sub_id":"101","register_pk":"162389","name":"長谷園登り窯","kana":"ながたにえんのぼりがま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊賀市丸柱字長谷569","lat":34.83702494,"lng":136.13052735,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"連房式登り窯、奥行34m、幅6.7m、石垣付","structure_material":"連房式登り窯","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0119","desc":"大正館の東南に位置する。南に高くなる傾斜地に設けられた登窯。幅４．５～６．７ｍ、高低差９．６ｍに設けられ、全長３４ｍを測る。直線上に一五の燃焼室が並ぶ連房式登り窯で、北に主焚き口を開ける。近世以来の伊賀焼の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009029"},{"id":"00010466","register_sub_id":"101","register_pk":"202516","name":"長谷園離れ","kana":"ながたにえんはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱569","lat":34.837573,"lng":136.129646,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0192","desc":"主屋の北西側に渡廊下を介して東西棟で建つ客間で、別荘へ渡るための機能も併せ持つ。木造平屋建、切妻造桟瓦葺で、下屋を廻らす。八畳二室を並べて三方を縁とし、西の主室に座敷飾を備える。庭側は開放するが、背面は左右の土蔵と外観の統一が図られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010466"},{"id":"00010465","register_sub_id":"101","register_pk":"199422","name":"長谷園別荘","kana":"ながたにえんべっそう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱569他","lat":34.837564,"lng":136.129403,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0191","desc":"敷地の西端に建つ、もと隠居部屋。主体部は二階建入母屋造で、上下階とも洗練された造作の和室二室をもつ。入母屋造の玄関脇に附属する洋間はパラペットに洋瓦を葺き、ベイウィンドウを開く。時代性をよく表す洋間付住宅で、茅葺屋根の主屋と好対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010465"},{"id":"00010475","register_sub_id":"101","register_pk":"202517","name":"長谷園門及び塀","kana":"ながたにえんもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱569他","lat":34.83739069,"lng":136.12948926,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"表門 木造、瓦葺、間口1.8m 西門 木造、瓦葺、間口1.7m 中庭門 木造、銅板葺、間口1.3m 塀 土塀、総延長106m","structure_material":"表門 木造","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0201","desc":"主屋正面の表門、別荘正面の西門、主屋と表門の間に建つ中庭門と、各門の間及び屋敷地背面を画す塀。表門は風格を備えた四脚門で、西門は隠居所入口らしく瀟洒な意匠の腕木門である。腰を竪板張とするなど敷地内建物との景観調和と格式の表徴が図られた門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010475"},{"id":"00009476","register_sub_id":"101","register_pk":"194269","name":"八太正太夫酒店蔵及び蔵前","kana":"はったしょうだゆうさけてんくらおよびくらまえ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県津市香良洲町1094","lat":34.64777802,"lng":136.53452287,"geo_status":"db","era":"明治中期／平成22年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造一部木造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造一部木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0128","desc":"敷地西側に建つ。土蔵造二階建、切妻造桟瓦葺の店蔵と木造二階建、寄棟造桟瓦葺の蔵前からなり、建築面積四六平方メートル。蔵前二階に数寄屋風の小座敷を設け、望楼風の外観を呈する。白漆喰塗大壁と腰に下見板を張る外壁と併せて、香良洲の景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009476"},{"id":"00009475","register_sub_id":"101","register_pk":"194268","name":"八太正太夫酒店主屋","kana":"はったしょうだゆうさけてんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県津市香良洲町1094","lat":34.64777599,"lng":136.53466682,"geo_status":"db","era":"明治前期／明治後期増築・昭和後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0127","desc":"敷地の北東に建ち、当初の主屋と北側に増築した新座敷、新座敷の東側へ突き出す角屋からなる。木造平屋建、当初主屋の西妻面は切妻造、東妻面は入母屋造、新座敷と角屋は切妻造で桟瓦葺、建築面積一七一平方メートル。歴代続く酒造業・地主の豪壮な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009475"},{"id":"00009478","register_sub_id":"101","register_pk":"194271","name":"八太正太夫酒店角蔵及び化粧室","kana":"はったしょうだゆうさけてんすみくらおよびけしょうしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県津市香良洲町1094","lat":34.64782596,"lng":136.53451894,"geo_status":"db","era":"明治17年／平成22年改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"土蔵造及び木造平屋建、瓦葺一部鉄板葺、建築面積8.5㎡","structure_material":"土蔵造及び木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0130","desc":"敷地北西隅に建つ。角蔵は土蔵造平屋建、切妻造桟瓦葺、西妻面に出入口を開き、木造平屋建、切妻造鉄板葺一部桟瓦葺の化粧室が蔵前となる。建築面積八平方メートル。基礎は玉石積とし下見板を腰高に張って鉢巻を廻し、外周する道路からの景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009478"},{"id":"00009477","register_sub_id":"101","register_pk":"194270","name":"八太正太夫酒店向い座敷及び下の蔵","kana":"はったしょうだゆうさけてんむかいざしきおよびしものくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県津市香良洲町1094","lat":34.64760991,"lng":136.53456463,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建及び土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"木造平屋建及び土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0129","desc":"敷地西側に建つ。木造二階建の向かい座敷の北側に土蔵造二階建の下の蔵が接して建ち、西面に土庇を設ける。建築面積五九平方メートル。南から下の蔵、向かい座敷、蔵前、店蔵、角蔵と建ち、白漆喰塗に下見板を腰高に張る外壁を連続させ良好な景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009477"},{"id":"00000536","register_sub_id":"101","register_pk":"101526","name":"福岡醤油店","kana":"ふくおかしょうゆてん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市島ヶ原1330","lat":34.78104581,"lng":136.05354834,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積204㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"24 － 0015","desc":"醤油醸造のための建物で，麹室やボイラー室を含む。付近は昭和28年に大きな水害を受けたが，この建物は難を逃れている。室内に設置されている醤油を絞るための「キリン圧搾機」はおそらく現役としては他に例を見ない貴重なものであり，広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000536"},{"id":"00010463","register_sub_id":"101","register_pk":"202515","name":"保田家住宅蔵","kana":"ほだけじゅうたくくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県名張市上本町21","lat":34.619924,"lng":136.090188,"geo_status":"db","era":"明治9頃／明治中期改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0189","desc":"敷地奥、主屋後方の突出部と連結している。桁行、梁間とも二間の二階建が当初部で、二階東妻に桁行一間半分を拡張している。切妻造桟瓦葺で、正面と東側面の腰は海鼠壁とするが、ほかは漆喰塗である。小規模だが、商家の屋敷構えを引き立てる土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010463"},{"id":"00010462","register_sub_id":"101","register_pk":"202514","name":"保田家住宅主屋","kana":"ほだけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県名張市上本町21","lat":34.619986,"lng":136.090286,"geo_status":"db","era":"明治9頃／昭和43改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積206㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0188","desc":"名張城下、神社参道の角地に位置する間口六間のつし二階建で、切妻造桟瓦葺。正面に竪格子構えの下屋を付け、内部は土間と板の間からなる広い吹抜の作業場をもつ特異な平面とする。正面外観は虫籠窓や格子窓、両端に袖壁を設け、城下の景観の重要な核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010462"},{"id":"00002773","register_sub_id":"101","register_pk":"103763","name":"松阪市文化財センター（旧カネボウ綿糸松阪工場綿糸倉庫）","kana":"まつさかしぶんかざいせんたー（きゅうかねぼうめんしまつさかこうじょうめんしそうこ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県松阪市外五曲町1","lat":34.57789675,"lng":136.520538,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"煉瓦造平屋建、鋼板葺、建築面積1044㎡","structure_material":"煉瓦造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"24 － 0044","desc":"鐘淵紡績松阪支店原綿倉庫として建設された。桁行約７４ｍ，梁間１０．６ｍの主体部の内部は桁行きに４室に区画し，正面には片流れの庇を付ける。煉瓦造イギリス積みで柱型を現した長大な外観を良くとどめるとともに，内部はギャラリーとして公開されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002773"},{"id":"00000053","register_sub_id":"101","register_pk":"101043","name":"宮崎本店事務所","kana":"みやざきほんてんじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市楠町南五味塚慶応950","lat":34.90975405,"lng":136.63386922,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積66㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0002","desc":"この地は，古くから鈴鹿川の伏流水を用いた酒造業が盛んであったが，宮崎本店は老舗酒造の一つである。木造モルタル塗，２階建の事務所は，２階外壁の一部をタイル張りとする住宅風の建物で，工場内唯一の洋風建築。正面妻壁上部のモチーフに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000053"},{"id":"00000056","register_sub_id":"101","register_pk":"101046","name":"宮崎本店第８倉庫","kana":"みやざきほんてんだいはちそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市楠町南五味塚慶応950","lat":34.90988317,"lng":136.63334316,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0006","desc":"貯蔵庫Ａ棟の北隣にある木造２階建ての倉庫で，近年背面（北）側に併設された。外壁は土壁であるが，現在は亜鉛引き鉄板で覆われる。搬入口は新しく改修されているが，軸部の保存はよい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000056"},{"id":"00000055","register_sub_id":"101","register_pk":"101045","name":"宮崎本店第４倉庫","kana":"みやざきほんてんだいよんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市楠町南五味塚慶応950","lat":34.90918973,"lng":136.63433311,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積655㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0005","desc":"貯蔵庫Ｂ棟の東隣にあるＬ型の木造２階建の大型倉庫で，元は酒蔵として造られたといわれる。構造的には３連の倉庫で，北側に搬入口を開き，１・２階とも窓を大きく開く点は他の倉庫群と異なる。整然とした外観は，酒造倉庫群の景観を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000055"},{"id":"00000057","register_sub_id":"101","register_pk":"101047","name":"宮崎本店貯蔵庫","kana":"みやざきほんてんちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県四日市市楠町南五味塚慶応950","lat":34.90971818,"lng":136.63352728,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積480㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0007","desc":"本店事務所の向かいに建つ複合建物で，並列する２棟の２階建倉庫をＨ型に連結した形式になり，各面に庇が取り付く。北側の道に面して茶色の煉瓦造の煙突が付属し，黒壁を基調とする周囲の景観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000057"},{"id":"00000054","register_sub_id":"101","register_pk":"101044","name":"宮崎本店貯蔵庫Ａ棟","kana":"みやざきほんてんちょぞうこえーとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県四日市市楠町南五味塚慶応950","lat":34.90969427,"lng":136.63319969,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積278㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0003","desc":"木造２階建，切妻造の重厚な構えになる大型の倉庫で，妻壁に亀甲宮の商標が描かれる。外壁の仕様は，他の倉庫群の仕様と異り，腰下が羽目板張りで，上部は下見板張りになって，一連の建物群のなかで中心的な存在であったことを示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000054"},{"id":"00014172","register_sub_id":"101","register_pk":"508802","name":"岩根醤油醸造店主屋","kana":"いわねしょうゆじょうぞうてんおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字八木屋町910他","lat":35.50335278,"lng":136.22665833,"geo_status":"db","era":"江戸末期／大正13年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0498","desc":"北国街道木之本宿の醤油醸造業を営む町家。街道に西面し、二階建切妻造平入桟瓦葺で一階は出格子構え、二階は両端に袖壁を設けて四箇所の窓を開け、軒は腕木で支持する。外壁は真壁造漆喰塗仕上。内部は南に土間、北に二列五室を配す。宿場の発展を示す町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014172"},{"id":"00001425","register_sub_id":"101","register_pk":"102415","name":"旧正野薬店店舗","kana":"きゅうしょうのやくてんてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字村井1283、1284","lat":35.01249231,"lng":136.25386555,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積117㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"25 － 0119","desc":"甲賀地方と並ぶ近江薬業の二大中心地である日野の薬店舗。平入り，つし二階建ての伝統的な町屋の形式からなる。二階は塗籠めとし，代表的な製薬「萬病感應丸」の看板を掲げる。地域の歴史的町並みの中核的な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001425"}];
